// induty_code → 섹터/업종 표시문자열 헬퍼 (없으면 빈 문자열 반환)
function _ksicSectorText(industryCode){
  if(!industryCode) return '';
  const code = String(industryCode).trim();
  const info = KSIC_MAP[code];
  if(!info) return '';
  return `${info.s} · ${info.n}`;
}

