  const _nb=_xmatNeed(st,'buy',bc.length), _ns=_xmatNeed(st,'sell',scc.length);   // [S1412]
  const _mb=_xmatMode(st,'buy'), _ms=_xmatMode(st,'sell'), _wb=_xmatWin(st,'buy'), _ws=_xmatWin(st,'sell');   // [S1413]
  const sig=_xmatSig(bc,scc,_nb,_ns,_mb,_ms,_wb,_ws);
