  if(c==='pending') return;
  if(!(bc.length||scc.length)){ window._trendXmatFireCache[key]={sig:sig, buy:null, sell:null, needB:0, needS:0}; cb&&cb(window._trendXmatFireCache[key]); return; }
  if(!(window.SXRecipeSignal && SXRecipeSignal.customCondBars)){ window._trendXmatFireCache[key]={sig:sig, buy:null, sell:null, needB:0, needS:0}; cb&&cb(null); return; }
  window._trendXmatFireCache[key]='pending';
