// [S1417] 계열 **토글** — 프리셋(덮어쓰기)에서 계열 단위 on/off로 바꿨다(사용자 요청).
//   그 계열이 **하나라도 꺼져 있으면 전부 켜고, 전부 켜져 있으면 전부 끈다**(전체 선택 체크박스와 같은 규약).
//   ⚠연속 13종은 계열이 없으므로 건드리지 않는다 — 개별 체크와 [비우기]로만 다룬다.
function _xmatKindTg(side, kind){
  const ctx=window._sxTrendCtx; if(!ctx) return; const mk=ctx.market; const st=_xmatStore(mk);
  const m=Object.assign({}, st[side]||{});
  const keys=[]; _DISCRIM_FEATS.forEach(D=>{ if(D.type!=='bool') return; if(!_xmatBoolOk(side,D.key)) return;
    if(_XMAT_KIND[D.key]===kind) keys.push(D.key); });
  if(!keys.length) return;
  const allOn = keys.every(k=>!!((m[k]||{}).on));
  keys.forEach(k=>{ if(allOn) delete m[k]; else m[k]={on:1}; });
  st[side]=m; _xmatSave(mk,st); try{ delete window._trendXmatFireCache[_trendRcpKey()]; }catch(_){} _trendRerender();
}
// [S1417] 계열별 켜짐 상태 — 'all' | 'some' | 'none'
function _xmatKindState(st, side, kind){
  const m=st[side]||{}; let on=0, tot=0;
  _DISCRIM_FEATS.forEach(D=>{ if(D.type!=='bool') return; if(!_xmatBoolOk(side,D.key)) return;
    if(_XMAT_KIND[D.key]!==kind) return; tot++; if((m[D.key]||{}).on) on++; });
  if(!tot) return 'none';
  return on===tot?'all':(on?'some':'none');
}
function _xmatSectionHtml(market){
  if(typeof _DISCRIM_FEATS==='undefined') return '';
  const st=_xmatStore(market);
  const bc=_xmatConds(st,'buy'), scc=_xmatConds(st,'sell');
  const openB=!!window._xmatOpenB, openS=!!window._xmatOpenS;
  const cache=(window._trendXmatFireCache||{})[(typeof _trendRcpKey==='function')?_trendRcpKey():''];
  const pending=(cache==='pending');
  const side=(sd,open,conds,title,col)=>{
    const m=st[sd]||{}; let rows='';
    if(open){
      _DISCRIM_FEATS.forEach(D=>{ if(D.type!=='num') return;
        const e=m[D.key]||{}; const on=!!e.on;
        const d=_xmatDefFor(sd,D.key); const dir=(e.dir==='gt'||e.dir==='lt')?e.dir:d.dir; const th=(e.th!=null&&isFinite(+e.th))?e.th:d.th;
        rows+=`<div style="display:flex;align-items:center;gap:5px;margin:3px 0;font-size:10px"><input type="checkbox" ${on?'checked':''} onchange="_xmatTg('${sd}','${D.key}')" style="width:15px;height:15px"><span style="flex:0 0 84px;color:${_XMAT_NEUTRAL[D.key]?'#d97706':'var(--text)'}">${_XMAT_NEUTRAL[D.key]?'⚖ ':''}${D.label}</span><select onchange="_xmatDir('${sd}','${D.key}',this.value)" style="font-size:11px;padding:2px;border-radius:5px;border:1px solid var(--border);background:var(--surface);color:var(--text)"><option value="lt"${dir==='lt'?' selected':''}>&lt;</option><option value="gt"${dir==='gt'?' selected':''}>&gt;</option></select><input type="number" value="${th}" inputmode="decimal" onchange="_xmatTh('${sd}','${D.key}',this.value)" style="width:58px;padding:3px;border:1px solid var(--border);border-radius:5px;font-size:11px;text-align:center;background:var(--surface);color:var(--text)"></div>`;
      });
      rows+=`<div style="font-size:8.5px;font-weight:700;color:var(--text3);margin:6px 0 2px">불리언 재료 (있음=참)</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 6px">`;
      // [S1412→S1415] 계열(바닥/과열/진행)별로 묶고 배지를 단다. ⚖ 중립은 맨 아래.
      //   ⚠순서: 그 쪽에 **어울리는 극단** → 반대 진행 → 나머지 → ⚖중립
      const _prim = (sd==='buy')?'ext-lo':'ext-hi';
      const _sec  = (sd==='buy')?'trend-dn':'trend-up';
      const _kbadge=k=>{ const t=_XMAT_KIND[k]; return t?`<span style="font-size:7.5px;font-weight:800;color:${_XMAT_KIND_COL[t]};border:1px solid ${_XMAT_KIND_COL[t]}66;border-radius:6px;padding:0 3px;margin-right:3px">${_XMAT_KIND_LBL[t]}</span>`:''; };
      const _cell=(D)=>{ const on=!!((m[D.key]||{}).on);
        return `<label style="display:flex;align-items:center;gap:3px;font-size:9.5px;color:var(--text)"><input type="checkbox" ${on?'checked':''} onchange="_xmatTg('${sd}','${D.key}')" style="width:14px;height:14px">${_kbadge(D.key)}${D.label}</label>`; };
      const _grp=(kinds)=>{ let h=''; _DISCRIM_FEATS.forEach(D=>{ if(D.type!=='bool') return; if(!_xmatBoolOk(sd,D.key)) return;
        if(_XMAT_NEUTRAL[D.key]) return; if(kinds.indexOf(_XMAT_KIND[D.key])<0) return; h+=_cell(D); }); return h; };
      const _rest=(()=>{ let h=''; _DISCRIM_FEATS.forEach(D=>{ if(D.type!=='bool') return; if(!_xmatBoolOk(sd,D.key)) return;
        if(_XMAT_NEUTRAL[D.key]) return; const t=_XMAT_KIND[D.key];
        if(t===_prim||t===_sec) return; h+=_cell(D); }); return h; })();
      const _hd=(t,c,note)=>`<div style="font-size:8.5px;font-weight:800;color:${c};margin:7px 0 2px">${t} <span style="font-weight:500;color:var(--text3)">${note}</span></div>`;
      rows+=`</div>`;
      { const a=_grp([_prim]), b=_grp([_sec]);
        if(a) rows+=_hd((sd==='buy'?'🟢 바닥·반전':'🔴 과열·반전'), _XMAT_KIND_COL[_prim], '이 프레임의 핵심')+`<div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 6px">${a}</div>`;
        if(b) rows+=_hd((sd==='buy'?'🔻 하락 진행':'🔺 상승 진행'), _XMAT_KIND_COL[_sec], (sd==='buy'?'⚠바닥 아님 — 떨어지는 칼날':'⚠과열 아님 — 달리는 말'))+`<div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 6px">${b}</div>`;
        if(_rest) rows+=_hd('· 반대 계열', 'var(--text3)', '이 프레임과 어긋남')+`<div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 6px;opacity:.75">${_rest}</div>`; }
      let _nb='';
      _DISCRIM_FEATS.forEach(D=>{ if(D.type!=='bool') return; if(!_xmatBoolOk(sd,D.key)) return; if(!_XMAT_NEUTRAL[D.key]) return; const on=!!((m[D.key]||{}).on);
        _nb+=`<label style="display:flex;align-items:center;gap:4px;font-size:9.5px;color:var(--text2)"><input type="checkbox" ${on?'checked':''} onchange="_xmatTg('${sd}','${D.key}')" style="width:14px;height:14px">${D.label}</label>`; });
      if(_nb) rows+=`<div style="font-size:8.5px;font-weight:700;color:#d97706;margin:7px 0 2px">⚖ 중립·양의성 (방향이 한쪽으로 안 갈리는 재료 — 배정은 그대로 두고 여기 모았습니다)</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 6px;opacity:.9">${_nb}</div>`;
      // [S1417] 계열 4개를 각각 on/off. 순서: 그 쪽의 핵심 → 같은쪽 진행 → 반대쪽 진행 → 반대 극단.
      const _kOrder = (sd==='buy') ? ['ext-lo','trend-dn','trend-up','ext-hi'] : ['ext-hi','trend-up','trend-dn','ext-lo'];
      const _kBtn=(kd)=>{ const stt=_xmatKindState(st, sd, kd); const c=_XMAT_KIND_COL[kd];
        const bg = stt==='all' ? `background:${c};color:#fff;border-color:${c}`
                 : stt==='some' ? `background:var(--surface2);color:${c};border-color:${c}`
                 : `background:var(--surface2);color:var(--text3);border-color:var(--border)`;
        const mk2 = stt==='all'?'☑':(stt==='some'?'◐':'☐');
        return `<span onclick="_sxVib(9);window._xmatKindTg&&_xmatKindTg('${sd}','${kd}')" style="font-size:9px;font-weight:800;padding:4px 10px;border-radius:8px;cursor:pointer;border:1px solid;${bg}">${mk2} ${_XMAT_KIND_LBL[kd]}</span>`; };
      rows+=`<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:6px">${_kOrder.map(_kBtn).join('')}</div>`
        +`<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:5px"><span onclick="_sxVib(9);window._xmatResetTh&&_xmatResetTh('${sd}')" style="font-size:9px;font-weight:700;padding:4px 10px;border-radius:8px;cursor:pointer;background:var(--surface2);color:var(--text2);border:1px solid var(--border)">↺ 임계 기본값</span><span onclick="_sxVib(9);window._xmatClear&&_xmatClear('${sd}')" style="font-size:9px;font-weight:700;padding:4px 10px;border-radius:8px;cursor:pointer;background:var(--surface2);color:var(--text3);border:1px solid var(--border)">비우기</span></div>`
        +`<div style="font-size:8px;color:var(--text3);margin-top:3px">☑ 전부 켜짐 · ◐ 일부 · ☐ 꺼짐 — 누르면 그 계열 전체가 토글됩니다(연속 13종은 개별 체크)</div>`;
    }
    // [S1412] 「N개 이상」 입력칸 — 제목행은 접기 토글이라 입력칸은 그 밖에 둔다(누르면 접히면 못 쓴다).
    const _need=_xmatNeed(st, sd, conds.length);
    const _mode=_xmatMode(st, sd), _win=_xmatWin(st, sd);
    const _cross=(sd==='buy')?'골든크로스':'데드크로스';
    const _modeTxt=(sd==='buy')
      ? (_mode==='and' ? '골든크로스 <b>그리고</b> 재료' : '골든크로스 <b>또는</b> 재료 — 재료만으로도 진입')
      : (_mode==='and' ? '데드크로스 <b>그리고</b> 재료 — 재료가 <b>청산 필터</b>(재앙손절은 예외로 항상 발동)' : '데드크로스 <b>또는</b> 재료 — 재료만으로도 청산');
    const _needRow=conds.length?(`<div style="display:flex;align-items:center;gap:5px;margin-top:5px;flex-wrap:wrap"><span style="font-size:9px;font-weight:800;color:${col}">${conds.length}개 중</span><input type="number" min="1" max="${conds.length}" value="${_need}" inputmode="numeric" onchange="window._xmatNeedSet&&_xmatNeedSet('${sd}',this.value)" style="width:56px;padding:3px;border:1px solid ${col}66;border-radius:6px;font-size:11px;font-weight:800;text-align:center;background:var(--surface);color:var(--text)"><span style="font-size:9px;font-weight:800;color:${col}">개 이상</span><span style="font-size:8.5px;color:var(--text3)">${_need>=conds.length?'(=모두·AND)':(_need<=1?'(=하나라도·OR)':'')}</span>`
      + `<span style="font-size:9px;font-weight:800;color:${col}">· 최근</span><input type="number" min="1" max="20" value="${_win}" inputmode="numeric" onchange="window._xmatWinSet&&_xmatWinSet('${sd}',this.value)" style="width:48px;padding:3px;border:1px solid ${col}66;border-radius:6px;font-size:11px;font-weight:800;text-align:center;background:var(--surface);color:var(--text)"><span style="font-size:9px;font-weight:800;color:${col}">봉 창</span><span style="font-size:8.5px;color:var(--text3)">${_win<=1?'(진입봉 단일)':''}</span></div>`
      + `<div style="display:flex;align-items:center;gap:6px;margin-top:5px;flex-wrap:wrap"><span onclick="_sxVib(9);window._xmatModeSet&&_xmatModeSet('${sd}')" style="font-size:10px;font-weight:800;padding:4px 11px;border-radius:12px;border:1px solid ${col};cursor:pointer;background:${col};color:#fff">${_cross} <b>${_mode==='and'?'AND':'OR'}</b> 재료</span><span style="font-size:8.5px;color:var(--text3);flex:1 1 100%;line-height:1.4">${_modeTxt}</span></div>`):'';
    // [S1418] ★접었을 때도 **켜진 계열**이 보이게 요약을 제목행에 붙인다.
    //   목적: 스크린샷 한 장으로 설정이 전달된다(사용자 요청 — "무엇이 적용됐는지 알려줄 수 있게").
    //   ⚠계산은 _xmatKindState 그대로다(버튼과 같은 값을 본다 — 한 화면이 두 말을 하지 않게).
    const _kOrd2 = (sd==='buy') ? ['ext-lo','trend-dn','trend-up','ext-hi'] : ['ext-hi','trend-up','trend-dn','ext-lo'];
    const _onKinds = _kOrd2.map(kd=>({kd:kd, s:_xmatKindState(st, sd, kd)})).filter(x=>x.s!=='none');
    const _numOn = conds.filter(c=>c.type==='num').length;
    const _kSum = _onKinds.length
      ? _onKinds.map(x=>`<span style="font-size:8.5px;font-weight:800;color:${_XMAT_KIND_COL[x.kd]};border:1px solid ${_XMAT_KIND_COL[x.kd]}66;border-radius:6px;padding:0 4px">${x.s==='all'?'☑':'◐'}${_XMAT_KIND_LBL[x.kd]}</span>`).join('')
      : `<span style="font-size:8.5px;color:var(--text3)">계열 없음</span>`;
    const _sumRow = `<div style="display:flex;align-items:center;gap:4px;flex-wrap:wrap;margin-top:3px">`
      +`<span style="font-size:8.5px;font-weight:700;color:var(--text3);min-width:26px">계열</span>${_kSum}`
      +(_numOn?`<span style="font-size:8.5px;font-weight:800;color:var(--text2);border:1px solid var(--border);border-radius:6px;padding:0 4px">연속 ${_numOn}</span>`:'')
      +`<span style="font-size:8.5px;font-weight:800;color:${col}">· ${_need}개↑ · 창${_win} · ${sd==='buy'?'골든':'데드'} ${_mode==='and'?'AND':'OR'}</span></div>`;
    return `<div style="margin-top:6px;border:1px solid var(--border);border-radius:8px;padding:6px 8px"><div onclick="_sxVib(8);window._xmatFold&&_xmatFold('${sd}')" style="cursor:pointer;display:flex;align-items:center;gap:6px"><span style="font-size:10px;font-weight:800;color:${col}">${open?'▼':'▶'} ${title}</span><span style="font-size:9px;color:${conds.length?col:'var(--text3)'};font-weight:700">${conds.length?(conds.length+'개 적용'):'미적용'}</span></div>${conds.length?_sumRow:''}${_needRow}${open?`<div style="margin-top:4px">${rows}</div>`:''}</div>`;
  };
  const lbl=c=>c.label+(c.type==='num'?((c.dir==='lt'?'<':'>')+c.th):'');
  return `<div style="margin:8px 0;padding:8px;border:1px dashed #7c3aed66;border-radius:10px">`
    +`<div style="font-size:10.5px;font-weight:800;color:#7c3aed">🧪 재료 조건 <span style="font-weight:500;font-size:8.5px;color:var(--text3)">빔서치 어휘(자유 조합 빌더 동일) · 진입봉 기준</span></div>`
    // [S1416] 헤더 설명이 다섯 줄이라 화면을 먹는다 ⇒ <details>로 접는다(기본 접힘). 표시만 · 동작 변경 0.
    +`<details><summary style="font-size:8.5px;font-weight:700;color:var(--text3);cursor:pointer;list-style:none;margin-top:2px">규약·범위 펼치기</summary>`
    +`<div style="font-size:8.5px;color:var(--text3);line-height:1.45;margin-top:2px">이 카드 BT·상세 모달·<b>📦 풀 전체 BT</b>에 적용 — <b>물타기 진단 미반영</b> · 재료는 250봉 웜업 후 평가(초반 진입 제외) · 임계 기본값=교과서 시작값(측정치 아님) · <b>[S1412] 매수·매도 모두 「N개 이상 충족」</b>(N=전체면 AND · N=1이면 OR) · <b>[S1413] 크로스와의 결합(AND/OR)·최근 N봉 창 선택</b> — 기본값은 전부 종전과 같음(매수 AND · 매도 OR · 창 1봉) · 불리언=방향 정합 재료만 표시 · ⚖ 중립·양의성은 아래 따로 모음 — 전체 어휘 실험은 자유 조합 빌더</div></details>`
    +(pending?`<div style="font-size:9px;color:#7c3aed;margin-top:4px">🧪 재료 스캔 중… (봉별 판정 · 첫 회만 무겁고 임계 수정은 즉시)</div>`:'')
    +side('buy',openB,bc,'🟢 매수 재료','#16a34a')
    +side('sell',openS,scc,'🔴 매도 재료 — 데드크로스에 추가','#e8365a')
    // [S1414] 적용 문구가 재료 98개에서 화면 절반을 먹었다 ⇒ <details>로 접는다. **기본 접힘**(open 속성 없음).
    //   ⚠<details>는 브라우저 기본 동작이라 상태 저장·리렌더 배선이 필요 없다(칩 토글과 달리 _trendRerender를 안 탄다).
    +((bc.length||scc.length)?`<details style="margin-top:5px"><summary style="font-size:8.5px;font-weight:700;color:var(--text3);cursor:pointer;list-style:none">적용 문구 펼치기 <span style="font-weight:500">(매수 ${bc.length} · 매도 ${scc.length})</span></summary><div style="font-size:8.5px;color:var(--text2);margin-top:4px;line-height:1.4">${bc.length?('매수['+bc.map(lbl).join('·')+']'):''}${(bc.length&&scc.length)?' · ':''}${scc.length?('매도['+scc.map(lbl).join('·')+']'):''}</div></details>`:'')
    +`</div>`;
}
if(typeof window!=='undefined'){ window._xmatTg=_xmatTg; window._xmatDir=_xmatDir; window._xmatTh=_xmatTh; window._xmatClear=_xmatClear; window._xmatFold=_xmatFold; }
// ═══════════ [S1120] 🧺 칸 바구니 — 3×3 칸(단기|장기·칸 사다리 정의와 동일)별 진입/청산 블록 조립 = 사용자 라우팅 ═══════════
//   바구니=블록 ON/OFF만 저장 · 파라미터(유예N·⏱N·ATR배수·Σ임계·혼재차단·kNN·💸)는 카드 전역 설정 공유.
//   포지션은 '진입 칸'의 바구니 청산 규칙을 끝까지 따름(칸 이동해도 유지 — 3×3 라우팅의 기존 관례와 동일).
//   칸 판정=stratSignalBars의 cellOf(cs.c) — 웜업(스캔 전 ~250봉) 봉은 칸 미확정=진입 제외. 모드: off/one(선택 칸만)/all(9칸 라우팅).
const _CB_VER=1;
const _CB_AX=['bull','mixed','bear'];
const _CB_SHORT={bull:'정',mixed:'혼',bear:'역'};
function _cbCellShort(k){ const p=String(k||'').split('|'); return (_CB_SHORT[p[0]]||'?')+'|'+(_CB_SHORT[p[1]]||'?'); }   // 단기|장기
function _cbStore(mk){ let st={_ver:_CB_VER,cells:{}}; try{ const raw=localStorage.getItem('SX_CELLBK_'+mk); if(raw){ const o=JSON.parse(raw); if(o&&o._ver===_CB_VER&&o.cells&&typeof o.cells==='object') st.cells=o.cells; } }catch(_){} return st; }
function _cbSave(mk,st){ try{ localStorage.setItem('SX_CELLBK_'+mk, JSON.stringify(st)); }catch(_){} }
function _cbGet(st,key){ const c=(st.cells||{})[key]||{}; return { en:Object.assign({cross:0,dc:0,pb:0,cell:0,bb:0,bv:0},c.en||{}), ex:Object.assign({dead:0,grace:0,fake:0,cfake:0,down:0,nbar:0,atr:0},c.ex||{}) }; }
function _cbBasketsAll(mk){ const st=_cbStore(mk); const b={}; _CB_AX.forEach(s=>_CB_AX.forEach(l=>{ const k=s+'|'+l; b[k]=_cbGet(st,k); })); return b; }
