  var lrDir = res.score>=30?1:res.score<=-30?-1:0;
  var aggHtml = '';
  if(knnDir!==0 && lrDir!==0){
    aggHtml = (knnDir===lrDir)
      ? ' <span style="font-size:9px;font-weight:700;color:#16a34a">· kNN+LR 합의</span>'
      : ' <span style="font-size:9px;font-weight:700;color:#dc2626">· kNN+LR 불일치</span>';
  }
