          pred:_d2.exp, naive:_d2.naive,
          aligned:(_tq0[_h2]!=null ? (_d2.exp <= _tq0[_h2]) : null),   // 측정 상단 안인가(=외삽 아님)
          ctx:_predCtx({ atr:atrPct, atrPctl:R._atrPctl, b:_d2.b, self:(_d2.self?1:0), n:_d2.n, c0:px }),
