  function _wm(map,keys){ var s=0,nn=0; keys.forEach(function(a){ if(map[a]&&map[a].n){ s+=map[a].ret*map[a].n; nn+=map[a].n; } }); return nn?{r:Math.round(s/nn*100)/100,n:nn}:null; }
