      var _cR=function(N){ var j=ei+N; return (rows[j] && typeof rows[j].close==='number') ? (rows[j].close/ep - 1) : null; };
      var _retN10=_cR(10);   // 종착(N10) 수익률 — 연속화(②). 단일봉(①③)은 여전히 취약 → 비교용.
      var _lateSum=0,_lateCnt=0;   // 후반평균 [+_LATE_FROM.._LATE_TO] — ①②③ 동시 해소(주력 지표).
      for(var _lk=_LATE_FROM;_lk<=_LATE_TO;_lk++){ var _lr=_cR(_lk); if(_lr!=null){ _lateSum+=_lr; _lateCnt++; } }
