      for(var _sk=1;_sk<=_SURV_TO;_sk++){ var _sc=(rows[ei+_sk] && typeof rows[ei+_sk].close==='number')?rows[ei+_sk].close:null; if(_sc!=null){ _survTot++; if(_sc>ep) _survUp++; } }
      var _surv=(_survTot>0)?(_survUp/_survTot):null;
