async function _btDiscrimRun(){
  var el=document.getElementById('btDiscrimResult'); if(!el) return;
  var mk=(typeof currentMarket!=='undefined')?currentMarket:'kr';
  el.style.display='block';
  var _prog=function(stage,i,t,n){ el.innerHTML='<div style="text-align:center;padding:14px;color:#0891b2;font-size:12px;font-weight:800">🧪 '+stage+' 재료 변별력 '+i+'/'+t+'<div style="font-size:10px;color:#94a3b8;font-weight:500;margin-top:4px">'+(n||'')+'</div></div>'; };
  el.innerHTML='<div style="text-align:center;padding:14px;color:#0891b2;font-size:12px;font-weight:800">🧪 측정 시작…</div>';
  await _trendBatchSleep(30);
  var rep=null, watch=null;
  try{ rep=await _btDiscrimBracket(mk,'rep',function(i,t,n){_prog('대표',i,t,n);}); }catch(e){ rep={ok:false,reason:String(e&&e.message||e)}; }
  await _trendBatchSleep(20);
  try{ watch=await _btDiscrimBracket(mk,'watch',function(i,t,n){_prog('관심',i,t,n);}); }catch(e2){ watch={ok:false,reason:String(e2&&e2.message||e2)}; }
  el.innerHTML=_btDiscrimRender(rep, watch, mk);
}
// [S833] 확장 풀(대표+관심+보강+top100 ~115종) 재료 변별력 — beam-search 풀 확장용. 결과 entries는 동일 window._sxLastDiscrimEntries에 저장 → 이어서 🌳 진짜전수/가짜전수 실행하면 확장 풀 기준 새 레시피 탐색.
// [S1047] _btDiscrimRunAll(확장풀 변별력) 제거 — 확장풀 폐지. 발굴풀 변별력(_btDiscrimRunMega)이 정본.
// [S846] 발굴 풀(대형) 재료 변별력 — 레시피 신호 3시장 확장용. 시장 전환 후 실행하면 그 시장 발굴 풀(KR200/US100/coin60)로 entries 생성 → 이어서 🌳 빔서치가 발굴 풀 기준 레시피 탐색. 결과 JSON에 mkt 포함(핸드오프 자기서술).
async function _btDiscrimRunMega(){
  var el=document.getElementById('btDiscrimResult'); if(!el) return;
  var mk=(typeof currentMarket!=='undefined')?currentMarket:'kr';
  var _n=(typeof _DISCOVERY_POOL!=='undefined'&&_DISCOVERY_POOL[mk])?_DISCOVERY_POOL[mk].length:0;
  el.style.display='block';
  var _prog=function(stage,i,t,n){ el.innerHTML='<div style="text-align:center;padding:14px;color:#0891b2;font-size:12px;font-weight:800">🌍 '+stage+' 재료 변별력 '+i+'/'+t+'<div style="font-size:10px;color:#94a3b8;font-weight:500;margin-top:4px">'+(n||'')+'</div></div>'; };
  if(window.SXCandleBT&&SXCandleBT.snapMode&&SXCandleBT.snapMode()&&SXCandleBT.snapHas&&!SXCandleBT.snapHas(mk)){   // [S847] 스냅샷 모드인데 이 시장 미로드 → 자동 로드(실패=중단, live 섞임 방지)
    el.innerHTML='<div style="text-align:center;padding:12px;color:#0e7490;font-size:11px;font-weight:800">📂 '+String(mk).toUpperCase()+' 스냅샷 자동 로드…</div>';
    var _sr=await _snapLoad(mk);
    if(!_sr.ok){ el.innerHTML='<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">📂 '+_sr.reason+'</div>'; return; }
    _snapBadge();
  }
  el.innerHTML='<div style="text-align:center;padding:14px;color:#0891b2;font-size:12px;font-weight:800">🌍 발굴 풀('+String(mk).toUpperCase()+' '+_n+'종) 측정 시작… <div style="font-size:10px;color:#94a3b8;font-weight:500;margin-top:4px">KR 200종 기준 수 분 소요 · 600봉 미만 자동 제외</div></div>';
  await _trendBatchSleep(30);
  var all=null;
  try{ all=await _btDiscrimBracket(mk,'mega',function(i,t,n){_prog('발굴풀',i,t,n);}); }catch(e){ all={ok:false,reason:String(e&&e.message||e)}; }
  el.innerHTML=_btDiscrimRender(all, null, mk);   // all-슬롯 렌더(확장풀과 동일 경로) → entries=발굴풀
}
if(typeof window!=='undefined'){ window._btDiscrimRunMega=_btDiscrimRunMega; }
