function _recipeIngRender(res, mk, poolLbl){
  var GRN='#16a34a', RED='#dc2626', AMB='#d97706', T2='var(--text2)', T3='var(--text3)';
  if(!res) return '';
  if(!res.ok) return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">💡 '+(res.reason||'측정 실패')+'</div>';
  var _esc=function(x){ return String(x==null?'':x).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); };
  var _side=function(sKey, label, col){
    var rows=res.agg[sKey], tot=0; rows.forEach(function(t){ tot+=t.n; });
    if(!tot) return '<div style="font-size:9px;color:'+T3+';margin:3px 0 7px"><b style="color:'+col+'">'+label+'</b>: 레짐 봉 없음</div>';
    var rowsH='', mono=[], gapAcc=[], trAcc=null;
    for(var i=0;i<rows.length;i++){
      var t=rows[i];
      var h15=t.n?(t.h15/t.n*100):null, a15=t.n?(t.s15/t.n*100):null;
      var uh=t.un?(t.uh15/t.un*100):null, fh=t.fn?(t.fh15/t.fn*100):null;
      var gap=(uh!=null&&fh!=null&&t.un>=15&&t.fn>=15)?(fh-uh):null;
      var tr3=t.tt?(t.tj[3]/t.tt*100):null;
      if(h15!=null&&t.n>=30) mono.push(h15);
      if(gap!=null) gapAcc.push(gap);
      if(i===rows.length-1&&tr3!=null) trAcc=tr3;
      var cOf=function(v){ return v==null?T3:(v>=60?GRN:(v>=52?AMB:RED)); };
      rowsH+='<tr>'
        +'<td style="padding:4px 6px;font-weight:800;color:'+T2+';font-size:10px">'+res.labels[i]+'</td>'
        +'<td style="padding:4px 6px;text-align:right;color:'+T3+';font-size:9px">'+t.n+'</td>'
        +'<td style="padding:4px 6px;text-align:right;font-weight:800;color:'+cOf(h15)+';font-size:11px">'+(h15!=null?h15.toFixed(0)+'%':'–')+'</td>'
        +'<td style="padding:4px 6px;text-align:right;color:'+((a15!=null&&a15>=0)?GRN:RED)+';font-size:9px">'+(a15!=null?((a15>=0?'+':'')+a15.toFixed(1)):'–')+'</td>'
        +'<td style="padding:4px 6px;text-align:right;font-weight:700;color:'+cOf(uh)+';font-size:10px">'+(uh!=null?uh.toFixed(0)+'%':'–')+'<span style="font-size:7.5px;color:'+T3+'"> n'+t.un+'</span></td>'
        +'<td style="padding:4px 6px;text-align:right;font-weight:700;color:'+cOf(fh)+';font-size:10px">'+(fh!=null?fh.toFixed(0)+'%':'–')+'<span style="font-size:7.5px;color:'+T3+'"> n'+t.fn+'</span></td>'
        +'<td style="padding:4px 6px;text-align:right;font-weight:800;color:'+(gap==null?T3:(gap>=5?GRN:(gap<=-5?RED:T3)))+';font-size:10px">'+(gap!=null?((gap>=0?'+':'')+gap.toFixed(0)+'p'):'–')+'</td>'
        +'<td style="padding:4px 6px;text-align:right;color:#0e7490;font-size:9.5px">'+(tr3!=null?tr3.toFixed(0)+'%':'–')+'</td>'
        +'</tr>';
    }
    var up=0; for(var m2=1;m2<mono.length;m2++){ if(mono[m2]>=mono[m2-1]-1) up++; }
    var monoOK=(mono.length>=3 && up>=mono.length-2);
    var G=gapAcc.length?(gapAcc.reduce(function(a,b){return a+b;},0)/gapAcc.length):null;
    var verdict='<b>A 방향성</b>: '+(mono.length<3?'표본 부족':(monoOK?'<span style="color:'+GRN+'">불↑=상승률↑ 단조 경향 — 재료 밀도에 방향성 있음</span>':'<span style="color:'+AMB+'">단조 아님 — 밀도 단독 점수화 근거 약함</span>'))
      +'<br><b>C 결합가치</b>: '+(G==null?'표본 부족':('같은 불 수에서 발동봉이 미발동 대비 평균 '+(G>=0?'+':'')+G.toFixed(1)+'%p'+(G>=5?' → <span style="color:'+GRN+'">AND 결합이 밀도 위에 실질 부가 — 레시피가 판정 단위</span>':(G<=-5?' → <span style="color:'+RED+'">역방향(재검)</span>':' → <span style="color:'+AMB+'">결합 부가가치 불명확</span>'))))
      +'<br><b>B 전이(준비 가설)</b>: 최고밀도(5+) 미발동봉의 3봉 내 발동율 '+(trAcc!=null?trAcc.toFixed(0)+'%':'—')+(trAcc!=null?(trAcc>=40?' → <span style="color:'+GRN+'">익어감=발동 예고 유효(준비축 근거)</span>':' → <span style="color:'+AMB+'">예고력 약함 — 준비축은 표시 참고용으로 한정</span>'):'');
    return '<div style="margin:2px 0 10px">'
      +'<div style="font-size:9.5px;font-weight:800;color:'+col+';margin-bottom:3px">'+label+' <span style="font-weight:500;color:'+T3+';font-size:8px">재료 사전 '+((res.dictK||{})[sKey]||'?')+'개 · 봉 '+tot+'</span></div>'
      +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
      +'<tr style="font-size:7.5px;color:'+T3+'"><td style="padding:3px 6px">불</td><td style="padding:3px 6px;text-align:right">n</td><td style="padding:3px 6px;text-align:right">t+15↑</td><td style="padding:3px 6px;text-align:right">평15</td><td style="padding:3px 6px;text-align:right">미발동↑</td><td style="padding:3px 6px;text-align:right">발동↑</td><td style="padding:3px 6px;text-align:right">Δ결합</td><td style="padding:3px 6px;text-align:right">전이3</td></tr>'
      +rowsH+'</table>'
      +'<div style="font-size:9px;margin-top:3px;line-height:1.6">'+verdict+'</div>'
      +'</div>';
  };
  var head='<div style="font-size:8.5px;color:'+T3+';line-height:1.5;margin-bottom:8px">💡 real 레시피를 <b>단일재료</b>로 분해(같은 지표·방향=가장 느슨한 임계로 통합) — 봉별 <b>불켜짐 수</b>의 세 질문. <b>A</b>: t+15↑가 불 수에 단조인가(방향성) · <b>C</b>: Δ결합=같은 불 수에서 발동−미발동(AND 부가가치, n각15↑만) · <b>B</b>: 전이3=미발동 봉이 3봉 내 발동할 확률(익어감 예고력). 레짐 일치 봉만·t+15 완성. 측정전용 · '+_esc(poolLbl||'')+' '+(res.stocksUsed||0)+'종목</div>';
  return head
    +_side('bear','🟢 하락장 — 바닥반등 재료','#16a34a')
    +_side('bull','🔵 상승장 — 눌림목 재료','#2563eb');
}
// ════════ [S876] ⏳ 전이 확정력 — 발동(전환) 후 조기 궤적(t+3 누적)이 최종 결과(시장 지평 t+7/10/15)를 가르는가. C 2.0 반등전이 축(확정/포기 판정)의 근거 + 조기 손절 규칙 데이터. 모집단=순수 real onset(xk=0·매수 후보와 동일). profileScan 재사용(모듈 무변경)·겹침3+ 병기(강신호의 조기하락 회복력)·미리보기 지원·측정전용. ════════
async function _recipeTransitBracket(mk, sources, onProgress){
  if(!(window.SXCandleBT&&SXCandleBT.fetchRows600)) return { ok:false, reason:'캔들 fetch 미연결' };
  if(!(window.SXRecipeSignal&&SXRecipeSignal.profileScan)) return { ok:false, reason:'레시피 모듈 구버전 — 새로고침' };
  var list=[], seen={};
  for(var si=0;si<sources.length;si++){
    var source=sources[si], part=[];
    if(source==='watch'){ try{ part=(typeof _getWatchlist==='function'?(_getWatchlist(mk)||[]):[]).filter(function(x){return x&&x.code;}).map(function(x){return {code:x.code,name:x.name||x.code};}); }catch(_){ part=[]; } }
    else if(source==='mega'){ part=(typeof _DISCOVERY_POOL!=='undefined'?(_DISCOVERY_POOL[mk]||[]):[]).map(function(x){ return Array.isArray(x)?{code:x[0],name:x[1]}:{code:String(x),name:String(x)}; }); }
    else { try{ var p=(window.SXCandleBT&&SXCandleBT.getRepPool)?SXCandleBT.getRepPool(mk):[]; part=(p||[]).map(function(x){return {code:x[0],name:x[1]};}); }catch(_){ part=[]; } }
    for(var pi=0;pi<part.length;pi++){ var it=part[pi]; if(it&&it.code&&!seen[it.code]){ seen[it.code]=1; list.push(it); } }
  }
  if(!list.length) return { ok:false, reason:'측정 풀 비어있음' };
  var CAP=(sources.indexOf('mega')>=0)?220:40, use=list.slice(0,CAP);
  var _tgt=(typeof _btTargetBars==='function')?_btTargetBars(mk,'day'):600, _floor=Math.floor(_tgt*0.95);
  var BK=[[-9,-0.02],[-0.02,0],[0,0.02],[0.02,9]], BKL=['≤−2%','−2~0','0~+2','+2%↑'];
  var mkT=function(){ return { n:0,h7:0,h10:0,h15:0,s15:0 }; };
  var agg={ bear:BK.map(function(){return {all:mkT(),hi:mkT()};}), bull:BK.map(function(){return {all:mkT(),hi:mkT()};}) };
  var stocksUsed=0;
  for(var i=0;i<use.length;i++){
    var s0=use[i];
    if(onProgress) onProgress(i+1, use.length, s0.name);
    await _trendBatchSleep(0);
    var rows=null; try{ rows=await SXCandleBT.fetchRows600(mk,'day',s0.code); }catch(e){}
    if(!Array.isArray(rows)||rows.length<_floor){ await _trendBatchSleep(6); continue; }
    var pr=null; try{ pr=await SXRecipeSignal.profileScan(s0.code, rows); }catch(e2){}
    if(!pr){ await _trendBatchSleep(6); continue; }
    var used=false;
    for(var ei=0;ei<pr.events.length;ei++){
      var ev=pr.events[ei];
      if(ev.kind!=='real' || (ev.xk>0)) continue;
      var e3=ev.cum[2]; if(e3==null) continue;
      var bk=-1;
      for(var k2=0;k2<BK.length;k2++){ if(e3>=BK[k2][0]&&e3<BK[k2][1]){ bk=k2; break; } }
      if(bk<0) continue;
      var q=agg[ev.lt][bk], tiers=[q.all]; if(ev.k>=3) tiers.push(q.hi);
      for(var ti=0;ti<tiers.length;ti++){
        var tg=tiers[ti]; tg.n++;
        if(ev.cum[6]>0)tg.h7++; if(ev.cum[9]>0)tg.h10++; if(ev.cum[14]>0)tg.h15++;
        tg.s15+=ev.cum[14];
      }
      used=true;
    }
    if(used) stocksUsed++;
    await _trendBatchSleep(10);
  }
  if(stocksUsed<3) return { ok:false, reason:'유효 종목 3개 미만' };
  return { ok:true, agg:agg, labels:BKL, stocksUsed:stocksUsed };
}
async function _recipeTransitRun(){
  var el=document.getElementById('recipeTransitResult'); if(!el) return;
  var mk=(typeof currentMarket!=='undefined')?currentMarket:'kr';
  el.style.display='block';
  var _prog=function(lbl,i,t,n){ el.innerHTML='<div style="padding:10px;font-size:11px;color:var(--text2)">⏳ '+lbl+' 스캔 '+i+'/'+t+' · '+(n||'')+'</div>'; };
  var res, poolLbl;
  if(window.SXCandleBT&&SXCandleBT.snapMode&&SXCandleBT.snapMode()){
    if(SXCandleBT.snapHas&&!SXCandleBT.snapHas(mk)){
      el.innerHTML='<div style="padding:10px;font-size:11px;font-weight:800;color:#0e7490">📂 '+String(mk).toUpperCase()+' 스냅샷 자동 로드…</div>';
      var _sr=await _snapLoad(mk);
      if(!_sr.ok){ el.innerHTML='<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">📂 '+_sr.reason+'</div>'; return; }
      if(typeof _snapBadge==='function') _snapBadge();
    }
    _prog('발굴풀',0,0,'시작');
    try{ res=await _recipeTransitBracket(mk,['mega'],function(i,t,n){_prog('발굴풀',i,t,n);}); }catch(eM){ res={ok:false,reason:String(eM&&eM.message||eM)}; }
    poolLbl='발굴풀(스냅샷)';
  } else {
    _prog('대표+관심',0,0,'시작');
    try{ res=await _recipeTransitBracket(mk,['rep','watch'],function(i,t,n){_prog('대표+관심',i,t,n);}); }catch(e){ res={ok:false,reason:String(e&&e.message||e)}; }
    poolLbl='대표+관심 합산';
  }
  _sxMeasStash('transit_'+mk, { poolLbl:poolLbl, res:res });   // [S876]
  el.innerHTML=_recipeTransitRender(res, mk, poolLbl);
}
function _recipeTransitRender(res, mk, poolLbl){
  var GRN='#16a34a', RED='#dc2626', AMB='#d97706', T2='var(--text2)', T3='var(--text3)';
  if(!res) return '';
  if(!res.ok) return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">⏳ '+(res.reason||'측정 실패')+'</div>';
  var _esc=function(x){ return String(x==null?'':x).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); };
  var _side=function(sKey, label, col){
    var rows=res.agg[sKey], tot=0; rows.forEach(function(q){ tot+=q.all.n; });
    if(!tot) return '<div style="font-size:9px;color:'+T3+';margin:3px 0 7px"><b style="color:'+col+'">'+label+'</b>: 순수발동 없음</div>';
    var rowsH='', worst=null, best=null;
    for(var i=0;i<rows.length;i++){
      var t=rows[i].all, hi=rows[i].hi;
      var h7=t.n?(t.h7/t.n*100):null, h10=t.n?(t.h10/t.n*100):null, h15=t.n?(t.h15/t.n*100):null, a15=t.n?(t.s15/t.n*100):null;
      if(i===0) worst={n:t.n, h15:h15, hiN:hi.n, hiH15:hi.n?(hi.h15/hi.n*100):null};
      if(i===rows.length-1) best={n:t.n, h15:h15};
      var cOf=function(v){ return v==null?T3:(v>=60?GRN:(v>=50?AMB:RED)); };
      rowsH+='<tr>'
        +'<td style="padding:4px 7px;font-weight:800;color:'+T2+';font-size:10px">'+res.labels[i]+'</td>'
        +'<td style="padding:4px 7px;text-align:right;color:'+T3+';font-size:9px">'+t.n+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:700;color:'+cOf(h7)+';font-size:10px">'+(h7!=null?h7.toFixed(0)+'%':'–')+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:800;color:'+cOf(h10)+';font-size:11px">'+(h10!=null?h10.toFixed(0)+'%':'–')+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:800;color:'+cOf(h15)+';font-size:11px">'+(h15!=null?h15.toFixed(0)+'%':'–')+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:700;color:'+((a15!=null&&a15>=0)?GRN:RED)+';font-size:9.5px">'+(a15!=null?((a15>=0?'+':'')+a15.toFixed(1)+'%'):'–')+'</td>'
        +'</tr>';
    }
    var verdict='';
    if(worst&&best&&worst.n>=20&&best.n>=20&&worst.h15!=null&&best.h15!=null){
      var spread=best.h15-worst.h15;
      verdict='조기 스프레드(+2%↑ vs ≤−2%): <b>'+(spread>=0?'+':'')+spread.toFixed(0)+'%p</b> — '
        +(spread>=20?'<span style="color:'+GRN+'">전이 판정 유효: 3봉 −2% 이탈=실패 전이(회복률 '+worst.h15.toFixed(0)+'%), 상방 유지=확정 진행</span>'
          :(spread>=10?'<span style="color:'+AMB+'">중간 — 조기 이탈이 열위지만 포기 규칙엔 근거 부족</span>'
            :'<span style="color:'+RED+'">조기 궤적 무정보 — 전이 판정 불가(지평까지 보유가 답)</span>'));
      if(worst.hiN>=15&&worst.hiH15!=null) verdict+='<br>겹침3+의 조기하락 회복률: <b>'+worst.hiH15.toFixed(0)+'%</b>(n'+worst.hiN+') vs 전체 '+worst.h15.toFixed(0)+'%'+((worst.hiH15-worst.h15)>=8?' → <span style="color:'+GRN+'">강신호는 조기 하락을 견딤(물타기 후보 구간)</span>':' → 강신호도 예외 아님');
    } else verdict='<span style="color:'+T3+'">표본 부족(양끝 n≥20 필요) — 판단 보류</span>';
    return '<div style="margin:2px 0 10px">'
      +'<div style="font-size:9.5px;font-weight:800;color:'+col+';margin-bottom:3px">'+label+' <span style="font-weight:500;color:'+T3+';font-size:8px">순수 onset n='+tot+'</span></div>'
      +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
      +'<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 7px">조기(t+3)</td><td style="padding:3px 7px;text-align:right">n</td><td style="padding:3px 7px;text-align:right">t+7↑</td><td style="padding:3px 7px;text-align:right">t+10↑</td><td style="padding:3px 7px;text-align:right">t+15↑</td><td style="padding:3px 7px;text-align:right">평15</td></tr>'
      +rowsH+'</table>'
      +'<div style="font-size:9px;margin-top:3px;line-height:1.6">'+verdict+'</div>'
      +'</div>';
  };
  var head='<div style="font-size:8.5px;color:'+T3+';line-height:1.5;margin-bottom:8px">⏳ <b>순수발동(전환) 후 조기 궤적</b>(t+3 누적)별 <b>최종 적중</b>(t+7/10/15) — 조기 상태가 결과를 가르면 <b>전이 판정</b>(확정/포기·조기 손절)의 근거. 겹침3+ 병기=강신호의 조기하락 회복력(물타기 질문). 스프레드 20%p↑=유효 · 10↑=중간 · 미만=무정보. 측정전용 · '+_esc(poolLbl||'')+' '+(res.stocksUsed||0)+'종목</div>';
  return head
    +_side('bear','🟢 하락장 — 발동 후 전이','#16a34a')
    +_side('bull','🔵 상승장 — 발동 후 전이','#2563eb');
}
// ════════ [S881] 🧭 임계 접근방향 — 수치 재료의 방향맹 보완(사용자 발견: 임계는 스냅샷, 위에서 내려온/밑에서 올라온 구분 부재). 순수 real onset의 발동 재료들을 전봉 대비 Δf 부호로 분해 — A 이벤트 종합(상승접근 비율 3버킷 t+k) + B 재료별(계열×접근 성과 → 빔서치 2.1 방향조건 근거). profileScan.ap 소비·미리보기 지원·측정전용. ════════
async function _recipeApprBracket(mk, sources, onProgress){
  if(!(window.SXCandleBT&&SXCandleBT.fetchRows600)) return { ok:false, reason:'캔들 fetch 미연결' };
  if(!(window.SXRecipeSignal&&SXRecipeSignal.profileScan)) return { ok:false, reason:'레시피 모듈 구버전 — 새로고침' };
  var list=[], seen={};
  for(var si=0;si<sources.length;si++){
    var source=sources[si], part=[];
    if(source==='watch'){ try{ part=(typeof _getWatchlist==='function'?(_getWatchlist(mk)||[]):[]).filter(function(x){return x&&x.code;}).map(function(x){return {code:x.code,name:x.name||x.code};}); }catch(_){ part=[]; } }
    else if(source==='mega'){ part=(typeof _DISCOVERY_POOL!=='undefined'?(_DISCOVERY_POOL[mk]||[]):[]).map(function(x){ return Array.isArray(x)?{code:x[0],name:x[1]}:{code:String(x),name:String(x)}; }); }
    else { try{ var p=(window.SXCandleBT&&SXCandleBT.getRepPool)?SXCandleBT.getRepPool(mk):[]; part=(p||[]).map(function(x){return {code:x[0],name:x[1]};}); }catch(_){ part=[]; } }
    for(var pi=0;pi<part.length;pi++){ var it=part[pi]; if(it&&it.code&&!seen[it.code]){ seen[it.code]=1; list.push(it); } }
  }
  if(!list.length) return { ok:false, reason:'측정 풀 비어있음' };
  var CAP=(sources.indexOf('mega')>=0)?220:40, use=list.slice(0,CAP);
  var _tgt=(typeof _btTargetBars==='function')?_btTargetBars(mk,'day'):600, _floor=Math.floor(_tgt*0.95);
  var mkT=function(){ return { n:0,h10:0,h15:0,s15:0 }; };
  var agg={ bear:[mkT(),mkT(),mkT()], bull:[mkT(),mkT(),mkT()] };   // 0=하강우세(<0.4) 1=균형 2=상승우세(>0.6)
  var fam={ bear:{}, bull:{} };                                      // key_dir → {up:{n,h15}, dn:{n,h15}}
  var stocksUsed=0, stale=false;
  for(var i=0;i<use.length;i++){
    var s0=use[i];
    if(onProgress) onProgress(i+1, use.length, s0.name);
    await _trendBatchSleep(0);
    var rows=null; try{ rows=await SXCandleBT.fetchRows600(mk,'day',s0.code); }catch(e){}
    if(!Array.isArray(rows)||rows.length<_floor){ await _trendBatchSleep(6); continue; }
    var pr=null; try{ pr=await SXRecipeSignal.profileScan(s0.code, rows); }catch(e2){}
    if(!pr){ await _trendBatchSleep(6); continue; }
    var used=false;
    for(var ei=0;ei<pr.events.length;ei++){
      var ev=pr.events[ei];
      if(ev.kind!=='real' || (ev.xk>0)) continue;
      if(typeof ev.ap==='undefined'){ stale=true; break; }
      if(!ev.ap) continue;
      var up=0,dn=0;
      for(var kk in ev.ap){ var d=ev.ap[kk];
        if(d===0) continue;
        var F=fam[ev.lt][kk]||(fam[ev.lt][kk]={up:{n:0,h15:0},dn:{n:0,h15:0}});
        var cell=(d>0)?F.up:F.dn; cell.n++; if(ev.cum[14]>0)cell.h15++;
        if(d>0)up++; else dn++;
      }
      var tot=up+dn; if(!tot) continue;
      var r=up/tot, bk=(r<0.4)?0:((r>0.6)?2:1);
      var tg=agg[ev.lt][bk];
      tg.n++; if(ev.cum[9]>0)tg.h10++; if(ev.cum[14]>0)tg.h15++; tg.s15+=ev.cum[14];
      used=true;
    }
    if(stale) return { ok:false, reason:'레시피 모듈 구버전(ap 없음) — 강력 새로고침 후 재실행' };
    if(used) stocksUsed++;
    await _trendBatchSleep(10);
  }
  if(stocksUsed<3) return { ok:false, reason:'유효 종목 3개 미만' };
  return { ok:true, agg:agg, fam:fam, stocksUsed:stocksUsed };
}
async function _recipeApprRun(){
  var el=document.getElementById('recipeApprResult'); if(!el) return;
  var mk=(typeof currentMarket!=='undefined')?currentMarket:'kr';
  el.style.display='block';
  var _prog=function(lbl,i,t,n){ el.innerHTML='<div style="padding:10px;font-size:11px;color:var(--text2)">🧭 '+lbl+' 스캔 '+i+'/'+t+' · '+(n||'')+'</div>'; };
  var res, poolLbl;
  if(window.SXCandleBT&&SXCandleBT.snapMode&&SXCandleBT.snapMode()){
    if(SXCandleBT.snapHas&&!SXCandleBT.snapHas(mk)){
      el.innerHTML='<div style="padding:10px;font-size:11px;font-weight:800;color:#0e7490">📂 '+String(mk).toUpperCase()+' 스냅샷 자동 로드…</div>';
      var _sr=await _snapLoad(mk);
      if(!_sr.ok){ el.innerHTML='<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">📂 '+_sr.reason+'</div>'; return; }
      if(typeof _snapBadge==='function') _snapBadge();
    }
    _prog('발굴풀',0,0,'시작');
    try{ res=await _recipeApprBracket(mk,['mega'],function(i,t,n){_prog('발굴풀',i,t,n);}); }catch(eM){ res={ok:false,reason:String(eM&&eM.message||eM)}; }
    poolLbl='발굴풀(스냅샷)';
  } else {
    _prog('대표+관심',0,0,'시작');
    try{ res=await _recipeApprBracket(mk,['rep','watch'],function(i,t,n){_prog('대표+관심',i,t,n);}); }catch(e){ res={ok:false,reason:String(e&&e.message||e)}; }
    poolLbl='대표+관심 합산';
  }
  _sxMeasStash('appr_'+mk, { poolLbl:poolLbl, res:res });   // [S881]
  el.innerHTML=_recipeApprRender(res, mk, poolLbl);
}
function _recipeApprRender(res, mk, poolLbl){
  var GRN='#16a34a', RED='#dc2626', AMB='#d97706', T2='var(--text2)', T3='var(--text3)';
  if(!res) return '';
  if(!res.ok) return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">🧭 '+(res.reason||'측정 실패')+'</div>';
  var _esc=function(x){ return String(x==null?'':x).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); };
  var LBL=['하강우세','균형','상승우세'];
  var _side=function(sKey, label, col){
    var rows=res.agg[sKey], tot=rows[0].n+rows[1].n+rows[2].n;
    if(!tot) return '<div style="font-size:9px;color:'+T3+';margin:3px 0 7px"><b style="color:'+col+'">'+label+'</b>: 순수발동 없음</div>';
    var rowsH='';
    for(var i=0;i<3;i++){
      var t=rows[i], h10=t.n?(t.h10/t.n*100):null, h15=t.n?(t.h15/t.n*100):null, a15=t.n?(t.s15/t.n*100):null;
      var cOf=function(v){ return v==null?T3:(v>=60?GRN:(v>=50?AMB:RED)); };
      rowsH+='<tr><td style="padding:4px 7px;font-weight:800;color:'+T2+';font-size:10px">'+LBL[i]+'</td>'
        +'<td style="padding:4px 7px;text-align:right;color:'+T3+';font-size:9px">'+t.n+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:800;color:'+cOf(h10)+';font-size:11px">'+(h10!=null?h10.toFixed(0)+'%':'–')+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:800;color:'+cOf(h15)+';font-size:11px">'+(h15!=null?h15.toFixed(0)+'%':'–')+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:700;color:'+((a15!=null&&a15>=0)?GRN:RED)+';font-size:9.5px">'+(a15!=null?((a15>=0?'+':'')+a15.toFixed(1)+'%'):'–')+'</td></tr>';
    }
    var vd='';
    var uN=rows[2].n, dN=rows[0].n;
    if(uN>=20&&dN>=20){
      var sp=(rows[2].h15/uN - rows[0].h15/dN)*100;
      vd=(Math.abs(sp)>=10)
        ? '<span style="color:'+GRN+'">접근방향 정보 있음 — '+(sp>0?'상승접근(회복형)':'하강접근(낙하형)')+' 우위 '+(sp>0?'+':'')+sp.toFixed(0)+'%p → 빔서치 2.1 방향조건 후보</span>'
        : '<span style="color:'+AMB+'">방향 격차 '+(sp>=0?'+':'')+sp.toFixed(0)+'%p — 유의미하지 않음(레벨이 지배)</span>';
    } else vd='<span style="color:'+T3+'">표본 부족(양끝 n≥20 필요) — 판단 보류</span>';
    // 재료별 top
    var F=res.fam[sKey], keys=Object.keys(F).sort(function(a,b){ return (F[b].up.n+F[b].dn.n)-(F[a].up.n+F[a].dn.n); }).slice(0,8);
    var famH='';
    keys.forEach(function(k){
      var f=F[k], un=f.up.n, dn2=f.dn.n;
      var uh=un?(f.up.h15/un*100):null, dh=dn2?(f.dn.h15/dn2*100):null;
      var gap=(un>=20&&dn2>=20&&uh!=null&&dh!=null)?(uh-dh):null;
      famH+='<tr><td style="padding:3px 6px;font-size:9px;font-weight:700;color:'+T2+'">'+_esc(k)+'</td>'
        +'<td style="padding:3px 6px;text-align:right;font-size:9.5px;color:'+(uh!=null?(uh>=60?GRN:(uh>=50?AMB:RED)):T3)+'">'+(uh!=null?uh.toFixed(0)+'%':'–')+'<span style="font-size:7.5px;color:'+T3+'"> n'+un+'</span></td>'
        +'<td style="padding:3px 6px;text-align:right;font-size:9.5px;color:'+(dh!=null?(dh>=60?GRN:(dh>=50?AMB:RED)):T3)+'">'+(dh!=null?dh.toFixed(0)+'%':'–')+'<span style="font-size:7.5px;color:'+T3+'"> n'+dn2+'</span></td>'
        +'<td style="padding:3px 6px;text-align:right;font-size:9.5px;font-weight:800;color:'+(gap==null?T3:(gap>=8?GRN:(gap<=-8?'#7c3aed':T3)))+'">'+(gap!=null?((gap>=0?'+':'')+gap.toFixed(0)+'p'):'–')+'</td></tr>';
    });
    return '<div style="margin:2px 0 10px">'
      +'<div style="font-size:9.5px;font-weight:800;color:'+col+';margin-bottom:3px">'+label+' <span style="font-weight:500;color:'+T3+';font-size:8px">순수 onset(ap 산출) 계 '+tot+'</span></div>'
      +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
      +'<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 7px">접근</td><td style="padding:3px 7px;text-align:right">n</td><td style="padding:3px 7px;text-align:right">t+10↑</td><td style="padding:3px 7px;text-align:right">t+15↑</td><td style="padding:3px 7px;text-align:right">평15</td></tr>'
      +rowsH+'</table>'
      +'<div style="font-size:9px;margin:3px 0 5px;line-height:1.5">'+vd+'</div>'
      +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
      +'<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 6px">재료(key_dir)</td><td style="padding:3px 6px;text-align:right">상승접근 t+15↑</td><td style="padding:3px 6px;text-align:right">하강접근 t+15↑</td><td style="padding:3px 6px;text-align:right">Δ(상−하)</td></tr>'
      +famH+'</table>'
      +'</div>';
  };
  var head='<div style="font-size:8.5px;color:'+T3+';line-height:1.5;margin-bottom:8px">🧭 <b>임계 접근방향</b> — 순수 real onset의 발동 재료(수치 조건)를 전봉 대비 Δf 부호로 분해. <b>lt+상승=회복형</b>(밑에서 올라옴)·lt+하강=낙하형 / gt+상승=점화형·gt+하강=소진형. A: 이벤트의 상승접근 비율 3버킷(&lt;40%/40~60%/&gt;60%) t+k · B: 재료 계열별 상승vs하강 접근 성과(Δ≥8p 초록=회복형 재료·≤−8p 보라=낙하형도 동력). 판정=양끝 t+15 격차 ±10%p. bin 재료(GC 등)는 태생 방향형이라 제외. 측정전용 · '+_esc(poolLbl||'')+' '+(res.stocksUsed||0)+'종목</div>';
  return head
    +_side('bear','🟢 하락장 — 바닥반등 접근방향','#16a34a')
    +_side('bull','🔵 상승장 — 눌림목 접근방향','#2563eb');
}
// ════════ [S883] 🔴 가짜반등(fake) 하락신호 본검증 — fake는 현재 real 순수성 판별자(혼재→votes0)+가짜반등 경보 배너일 뿐. 독립 "하락 판정" 신호로 승격 가능한가. profileScan의 fake 이벤트를 순수발동(xk=0)으로 재집계 3측정: ①순수 프로파일 t+k 하락적중(cum<0) vs base 하락률=리프트 ②겹침(fakeK) 사다리 단조 ③조기궤적(t+3 이탈이 하락 확정 앞당기나·전이의 거울상). 씨앗(S865 신세트·0701 in-sample): kr 역배 t+15 58%(+12p)·us 정배 t+7 63%(+16p). 판정 후 프레임 합의(청산경보 vs C 하락 투표자). 미리보기 세트 지원(_R() 경유)·측정전용. ════════
async function _recipeFakeDownBracket(mk, sources, onProgress){
  if(!(window.SXCandleBT&&SXCandleBT.fetchRows600)) return { ok:false, reason:'캔들 fetch 미연결' };
  if(!(window.SXRecipeSignal&&SXRecipeSignal.profileScan)) return { ok:false, reason:'레시피 모듈 구버전 — 새로고침' };
  var list=[], seen={};
  for(var si=0;si<sources.length;si++){
    var source=sources[si], part=[];
    if(source==='watch'){ try{ part=(typeof _getWatchlist==='function'?(_getWatchlist(mk)||[]):[]).filter(function(x){return x&&x.code;}).map(function(x){return {code:x.code,name:x.name||x.code};}); }catch(_){ part=[]; } }
    else if(source==='mega'){ part=(typeof _DISCOVERY_POOL!=='undefined'?(_DISCOVERY_POOL[mk]||[]):[]).map(function(x){ return Array.isArray(x)?{code:x[0],name:x[1]}:{code:String(x),name:String(x)}; }); }
    else { try{ var p=(window.SXCandleBT&&SXCandleBT.getRepPool)?SXCandleBT.getRepPool(mk):[]; part=(p||[]).map(function(x){return {code:x[0],name:x[1]};}); }catch(_){ part=[]; } }
    for(var pi=0;pi<part.length;pi++){ var it=part[pi]; if(it&&it.code&&!seen[it.code]){ seen[it.code]=1; list.push(it); } }
  }
  if(!list.length) return { ok:false, reason:'측정 풀 비어있음' };
  var CAP=(sources.indexOf('mega')>=0)?220:40, use=list.slice(0,CAP);
  var _tgt=(typeof _btTargetBars==='function')?_btTargetBars(mk,'day'):600, _floor=Math.floor(_tgt*0.95);
  var H=20, z=function(){ return new Array(H).fill(0); };
  var base={ bear:{n:0,up:z(),sum:z()}, bull:{n:0,up:z(),sum:z()} };   // 레짐 전체 완성봉(발동 무관) — 하락률 기준선(profileScan.base 누적·hit=상승수)
  var prof={ bear:{n:0,dn:z(),sum:z()}, bull:{n:0,dn:z(),sum:z()} };   // 순수 fake(xk=0): dn[j]=하락(cum<0)수 · sum[j]=수익합
  var LAD=function(){ return [{n:0,dn:0},{n:0,dn:0},{n:0,dn:0}]; };
  var ladder={ bear:LAD(), bull:LAD() };                               // 겹침(fakeK) 사다리 1/2/3+ → t+15 하락
  var BK=[[-9,-0.02],[-0.02,0],[0,0.02],[0.02,9]], BKL=['≤−2%','−2~0','0~+2','+2%↑'];
  var EAR=function(){ return BK.map(function(){return {n:0,dn:0};}); };
  var early={ bear:EAR(), bull:EAR() };                                // 조기궤적: cum[2] 4버킷 → t+15 하락(전이 거울상)
  var stocksUsed=0;
  for(var i=0;i<use.length;i++){
    var s0=use[i];
    if(onProgress) onProgress(i+1, use.length, s0.name);
    await _trendBatchSleep(0);
    var rows=null; try{ rows=await SXCandleBT.fetchRows600(mk,'day',s0.code); }catch(e){}
    if(!Array.isArray(rows)||rows.length<_floor){ await _trendBatchSleep(6); continue; }
    var pr=null; try{ pr=await SXRecipeSignal.profileScan(s0.code, rows); }catch(e2){}
    if(!pr){ await _trendBatchSleep(6); continue; }
    ['bear','bull'].forEach(function(sd){ var pb=pr.base&&pr.base[sd]; if(!pb) return; var B=base[sd]; B.n+=(pb.n||0); for(var j=0;j<H;j++){ B.up[j]+=(pb.hit&&pb.hit[j])||0; B.sum[j]+=(pb.sum&&pb.sum[j])||0; } });
    var used=false;
    for(var ei=0;ei<pr.events.length;ei++){
      var ev=pr.events[ei];
      if(ev.kind!=='fake' || (ev.xk>0)) continue;                     // 순수 fake(real 무동반)만
      var side=ev.lt; if(side!=='bear'&&side!=='bull') continue;
      var P=prof[side]; P.n++;
      for(var j2=0;j2<H;j2++){ if(ev.cum[j2]<0)P.dn[j2]++; P.sum[j2]+=ev.cum[j2]; }
      var d15=(ev.cum[14]<0)?1:0;
      var tier=(ev.k>=3)?2:(ev.k===2?1:0);
      var Lq=ladder[side][tier]; Lq.n++; Lq.dn+=d15;
      var e3=ev.cum[2];
      if(e3!=null){ var bk=-1; for(var k2=0;k2<BK.length;k2++){ if(e3>=BK[k2][0]&&e3<BK[k2][1]){ bk=k2; break; } } if(bk>=0){ var Eq=early[side][bk]; Eq.n++; Eq.dn+=d15; } }
      used=true;
    }
    if(used) stocksUsed++;
    await _trendBatchSleep(10);
  }
  if(stocksUsed<3) return { ok:false, reason:'유효 종목 3개 미만(순수 fake 발동 부족)' };
  return { ok:true, base:base, prof:prof, ladder:ladder, early:early, labels:BKL, stocksUsed:stocksUsed };
}
async function _recipeFakeDownRun(){
  var el=document.getElementById('recipeFakeResult'); if(!el) return;
  var mk=(typeof currentMarket!=='undefined')?currentMarket:'kr';
  el.style.display='block';
  var _prog=function(lbl,i,t,n){ el.innerHTML='<div style="padding:10px;font-size:11px;color:var(--text2)">🔴 '+lbl+' 스캔 '+i+'/'+t+' · '+(n||'')+'</div>'; };
  var res, poolLbl;
  if(window.SXCandleBT&&SXCandleBT.snapMode&&SXCandleBT.snapMode()){
    if(SXCandleBT.snapHas&&!SXCandleBT.snapHas(mk)){
      el.innerHTML='<div style="padding:10px;font-size:11px;font-weight:800;color:#0e7490">📂 '+String(mk).toUpperCase()+' 스냅샷 자동 로드…</div>';
      var _sr=await _snapLoad(mk);
      if(!_sr.ok){ el.innerHTML='<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">📂 '+_sr.reason+'</div>'; return; }
      if(typeof _snapBadge==='function') _snapBadge();
    }
    _prog('발굴풀',0,0,'시작');
    try{ res=await _recipeFakeDownBracket(mk,['mega'],function(i,t,n){_prog('발굴풀',i,t,n);}); }catch(eM){ res={ok:false,reason:String(eM&&eM.message||eM)}; }
    poolLbl='발굴풀(스냅샷)';
  } else {
    _prog('대표+관심',0,0,'시작');
    try{ res=await _recipeFakeDownBracket(mk,['rep','watch'],function(i,t,n){_prog('대표+관심',i,t,n);}); }catch(e){ res={ok:false,reason:String(e&&e.message||e)}; }
    poolLbl='대표+관심 합산';
  }
  _sxMeasStash('fakedown_'+mk, { poolLbl:poolLbl, res:res });   // [S883]
  el.innerHTML=_recipeFakeDownRender(res, mk, poolLbl);
}
function _recipeFakeDownRender(res, mk, poolLbl){
  var GRN='#16a34a', RED='#dc2626', AMB='#d97706', T2='var(--text2)', T3='var(--text3)';
  if(!res) return '';
  if(!res.ok) return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">🔴 '+(res.reason||'측정 실패')+'</div>';
  var _esc=function(x){ return String(x==null?'':x).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); };
  var HZ=[[2,'t+3'],[4,'t+5'],[6,'t+7'],[9,'t+10'],[14,'t+15']];
  var _side=function(sKey, label, col){
    var P=res.prof[sKey], B=res.base[sKey], L=res.ladder[sKey], E=res.early[sKey];
    if(!P || !P.n) return '<div style="font-size:9px;color:'+T3+';margin:3px 0 9px"><b style="color:'+col+'">'+label+'</b>: 순수 fake 발동 없음</div>';
    var rowsH='', maxLift=null, maxLiftHz='';
    for(var i=0;i<HZ.length;i++){
      var idx=HZ[i][0];
      var dn=P.dn[idx]/P.n*100;
      var bs=B.n?(1-B.up[idx]/B.n)*100:null;
      var lift=(bs!=null)?(dn-bs):null;
      var avg=P.sum[idx]/P.n*100;
      if(lift!=null && (maxLift==null || lift>maxLift)){ maxLift=lift; maxLiftHz=HZ[i][1]; }
      var cLift=(lift==null)?T3:(lift>=10?GRN:(lift>=5?AMB:RED));
      rowsH+='<tr>'
        +'<td style="padding:4px 7px;font-weight:800;color:'+T2+';font-size:10px">'+HZ[i][1]+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:700;color:'+T2+';font-size:10.5px">'+dn.toFixed(0)+'%</td>'
        +'<td style="padding:4px 7px;text-align:right;color:'+T3+';font-size:9.5px">'+(bs!=null?bs.toFixed(0)+'%':'–')+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:800;color:'+cLift+';font-size:11px">'+(lift!=null?((lift>=0?'+':'')+lift.toFixed(0)+'p'):'–')+'</td>'
        +'<td style="padding:4px 7px;text-align:right;font-weight:700;color:'+(avg<0?RED:T3)+';font-size:9.5px">'+((avg>=0?'+':'')+avg.toFixed(1)+'%')+'</td>'
        +'</tr>';
    }
    var pv='';
    if(maxLift!=null){
      pv=(maxLift>=10?'<span style="color:'+GRN+'">유효 하락신호 — 최대 리프트 '+maxLiftHz+' <b>+'+maxLift.toFixed(0)+'p</b>(base 초과=fake 고유 예측력)</span>'
        :(maxLift>=5?'<span style="color:'+AMB+'">약한 신호 — 최대 리프트 '+maxLiftHz+' +'+maxLift.toFixed(0)+'p</span>'
          :'<span style="color:'+RED+'">무정보 — base 하락률 대비 리프트 미미(fake=순수성 판별자에 머묾)</span>'));
    }
    var ladTxt='';
    (function(){
      var lbl=['1','2','3+'], seg=[];
      for(var t=0;t<3;t++){ var q=L[t]; seg.push('<b>'+lbl[t]+'</b>('+q.n+') '+(q.n?(q.dn/q.n*100).toFixed(0)+'%':'–')); }
      var r1=L[0].n?L[0].dn/L[0].n*100:null, r3=L[2].n?L[2].dn/L[2].n*100:null, mono;
      if(r1!=null&&r3!=null&&L[0].n>=15&&L[2].n>=15){ var dd=r3-r1; mono=(dd>=8?' → <span style="color:'+GRN+'">겹침↑→하락↑ 단조(+'+dd.toFixed(0)+'p)</span>':' → <span style="color:'+T3+'">단조 약함('+(dd>=0?'+':'')+dd.toFixed(0)+'p)</span>'); }
      else mono=' → <span style="color:'+T3+'">표본 부족</span>';
      ladTxt='<div style="font-size:9px;color:'+T3+';margin:2px 0 1px">겹침 사다리(t+15 하락): '+seg.join(' · ')+mono+'</div>';
    })();
    var earTxt='';
    (function(){
      var seg=[];
      for(var t=0;t<4;t++){ var q=E[t]; seg.push('<b>'+res.labels[t]+'</b>('+q.n+') '+(q.n?(q.dn/q.n*100).toFixed(0)+'%':'–')); }
      var a=E[0].n?E[0].dn/E[0].n*100:null, d=E[3].n?E[3].dn/E[3].n*100:null, sp;
      if(a!=null&&d!=null&&E[0].n>=15&&E[3].n>=15){ var ss=a-d; sp=(ss>=10?' → <span style="color:'+GRN+'">조기 −2% 이탈=하락 확정 앞당김(+'+ss.toFixed(0)+'p)</span>':(ss<=-10?' → <span style="color:'+AMB+'">역방향(조기 반등=하락 약화)</span>':' → <span style="color:'+T3+'">조기 무정보</span>')); }
      else sp=' → <span style="color:'+T3+'">표본 부족</span>';
      earTxt='<div style="font-size:9px;color:'+T3+';margin:1px 0 2px">조기궤적(t+3별 t+15 하락): '+seg.join(' · ')+sp+'</div>';
    })();
    return '<div style="margin:2px 0 11px">'
      +'<div style="font-size:9.5px;font-weight:800;color:'+col+';margin-bottom:3px">'+label+' <span style="font-weight:500;color:'+T3+';font-size:8px">순수 fake onset n='+P.n+'</span></div>'
      +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
      +'<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 7px">지평</td><td style="padding:3px 7px;text-align:right">하락%</td><td style="padding:3px 7px;text-align:right">base</td><td style="padding:3px 7px;text-align:right">리프트</td><td style="padding:3px 7px;text-align:right">평균</td></tr>'
      +rowsH+'</table>'
      +'<div style="font-size:9px;margin:3px 0 4px;line-height:1.55">'+pv+'</div>'
      +ladTxt+earTxt
      +'</div>';
  };
  var head='<div style="font-size:8.5px;color:'+T3+';line-height:1.5;margin-bottom:8px">🔴 <b>가짜반등(fake) 하락신호 본검증</b> — fake 순수발동(real 무동반) 후 <b>하락적중</b>(cum&lt;0)이 <b>base 하락률</b>(레짐 전체 봉)을 넘으면 fake 고유의 하락 예측력. ①지평별 리프트(≥10p 유효·5~10 약함) ②겹침 사다리 단조(3+ vs 1 ≥8p) ③조기궤적(조기 −2% 이탈=확정 앞당김 ±10p). ⚠<b>in-sample</b>(0701 렌즈채굴 지반)·표본 n&lt;15~20 주의 · '+_esc(poolLbl||'')+' '+(res.stocksUsed||0)+'종목</div>';
  return head
    +_side('bear','🔴 하락장 — fake 가짜반등→하락','#dc2626')
    +_side('bull','🔵 상승장 — fake 가짜눌림목→하락','#2563eb');
}

// ════════ [S885] 🟡 전이형(transition-bear) 위험 측정 — S880 발견(lt='mixed'&단기비정배 = 게이트·레시피 범위 밖인데 KCTC −35% 실재)을 정량화. 정의 확장 금지(발굴풀 모집단 보존) 대신 별도 측정: baseRateScan 전 봉(발동 무관)을 4버킷 분류(bull/bear/transit/상승전이) → ①빈도(transit 봉 비율 ≥10%=실질) ②base 위험도(transit N10 상승률·평균수익 vs 하락장 base — 같거나 낮으면 bear급 위험 확정). 결과 갈림: 위험 확인 → S886 transit 발굴+③재료변별(deadcat 불켜짐, 봉별 f 필요→signal측) / 희소·안전 → 🟡 배너 유지로 종결. window-only(baseRateScan 노출)·미리보기 지원·측정전용. ════════
async function _recipeTransitRiskBracket(mk, sources, onProgress){
  if(!(window.SXCandleBT&&SXCandleBT.fetchRows600)) return { ok:false, reason:'캔들 fetch 미연결' };
  if(!(window.SXRecipeSignal&&SXRecipeSignal.baseRateScan)) return { ok:false, reason:'레시피 모듈 구버전(baseRateScan 없음) — 새로고침' };
  var list=[], seen={};
  for(var si=0;si<sources.length;si++){
    var source=sources[si], part=[];
    if(source==='watch'){ try{ part=(typeof _getWatchlist==='function'?(_getWatchlist(mk)||[]):[]).filter(function(x){return x&&x.code;}).map(function(x){return {code:x.code,name:x.name||x.code};}); }catch(_){ part=[]; } }
    else if(source==='mega'){ part=(typeof _DISCOVERY_POOL!=='undefined'?(_DISCOVERY_POOL[mk]||[]):[]).map(function(x){ return Array.isArray(x)?{code:x[0],name:x[1]}:{code:String(x),name:String(x)}; }); }
    else { try{ var p=(window.SXCandleBT&&SXCandleBT.getRepPool)?SXCandleBT.getRepPool(mk):[]; part=(p||[]).map(function(x){return {code:x[0],name:x[1]};}); }catch(_){ part=[]; } }
    for(var pi=0;pi<part.length;pi++){ var it=part[pi]; if(it&&it.code&&!seen[it.code]){ seen[it.code]=1; list.push(it); } }
  }
  if(!list.length) return { ok:false, reason:'측정 풀 비어있음' };
  var CAP=(sources.indexOf('mega')>=0)?220:40, use=list.slice(0,CAP);
  var _tgt=(typeof _btTargetBars==='function')?_btTargetBars(mk,'day'):600, _floor=Math.floor(_tgt*0.95);
  var MK=function(){ return { total:0, n:0, up:0, sret:0 }; };   // total=전 봉(빈도용) · n=N10완성봉 · up=상승수 · sret=수익합
  var buck={ bull:MK(), bear:MK(), transit:MK(), uptransit:MK() };
  var offTotal=0, stocksUsed=0;
  for(var i=0;i<use.length;i++){
    var s0=use[i];
    if(onProgress) onProgress(i+1, use.length, s0.name);
    await _trendBatchSleep(0);
    var rows=null; try{ rows=await SXCandleBT.fetchRows600(mk,'day',s0.code); }catch(e){}
    if(!Array.isArray(rows)||rows.length<_floor){ await _trendBatchSleep(6); continue; }
    var br=null; try{ br=await SXRecipeSignal.baseRateScan(s0.code, rows); }catch(e2){}
    if(!Array.isArray(br)||!br.length){ await _trendBatchSleep(6); continue; }
    var used=false;
    for(var bi=0;bi<br.length;bi++){
      var r=br[bi], key;
      if(r.lt==='bull') key='bull';
      else if(r.lt==='bear') key='bear';
      else if(r.lt==='mixed') key=(r.stBull)?'uptransit':'transit';   // 전이형=장기혼조+단기비정배 · 상승전이=장기혼조+단기정배
      else { offTotal++; continue; }                                   // off=장기MA 데이터부족(웜업) 제외
      var q=buck[key]; q.total++;
      if(r.complete && r.ret!=null){ q.n++; if(r.up)q.up++; q.sret+=r.ret; }
      used=true;
    }
    if(used) stocksUsed++;
    await _trendBatchSleep(8);
  }
  if(stocksUsed<3) return { ok:false, reason:'유효 종목 3개 미만' };
  return { ok:true, buck:buck, offTotal:offTotal, stocksUsed:stocksUsed };
}
async function _recipeTransitRiskRun(){
  var el=document.getElementById('recipeTransitRiskResult'); if(!el) return;
  var mk=(typeof currentMarket!=='undefined')?currentMarket:'kr';
  el.style.display='block';
  var _prog=function(lbl,i,t,n){ el.innerHTML='<div style="padding:10px;font-size:11px;color:var(--text2)">🟡 '+lbl+' 스캔 '+i+'/'+t+' · '+(n||'')+'</div>'; };
  var res, poolLbl;
  if(window.SXCandleBT&&SXCandleBT.snapMode&&SXCandleBT.snapMode()){
    if(SXCandleBT.snapHas&&!SXCandleBT.snapHas(mk)){
      el.innerHTML='<div style="padding:10px;font-size:11px;font-weight:800;color:#0e7490">📂 '+String(mk).toUpperCase()+' 스냅샷 자동 로드…</div>';
      var _sr=await _snapLoad(mk);
      if(!_sr.ok){ el.innerHTML='<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">📂 '+_sr.reason+'</div>'; return; }
      if(typeof _snapBadge==='function') _snapBadge();
    }
    _prog('발굴풀',0,0,'시작');
    try{ res=await _recipeTransitRiskBracket(mk,['mega'],function(i,t,n){_prog('발굴풀',i,t,n);}); }catch(eM){ res={ok:false,reason:String(eM&&eM.message||eM)}; }
    poolLbl='발굴풀(스냅샷)';
  } else {
    _prog('대표+관심',0,0,'시작');
    try{ res=await _recipeTransitRiskBracket(mk,['rep','watch'],function(i,t,n){_prog('대표+관심',i,t,n);}); }catch(e){ res={ok:false,reason:String(e&&e.message||e)}; }
    poolLbl='대표+관심 합산';
  }
  _sxMeasStash('transitrisk_'+mk, { poolLbl:poolLbl, res:res });   // [S885]
  el.innerHTML=_recipeTransitRiskRender(res, mk, poolLbl);
}
function _recipeTransitRiskRender(res, mk, poolLbl){
  var GRN='#16a34a', RED='#dc2626', AMB='#d97706', YEL='#ca8a04', T2='var(--text2)', T3='var(--text3)';
  if(!res) return '';
  if(!res.ok) return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">🟡 '+(res.reason||'측정 실패')+'</div>';
  var _esc=function(x){ return String(x==null?'':x).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); };
  var b=res.buck, regime=b.bull.total+b.bear.total+b.transit.total+b.uptransit.total;
  var pctUp=function(q){ return q.n?q.up/q.n*100:null; };
  var avg=function(q){ return q.n?q.sret/q.n*100:null; };
  var freq=function(q){ return regime?q.total/regime*100:null; };
  var ROWS=[['bull','🔵 상승장',T2],['bear','🔴 하락장',RED],['transit','🟡 전이형(하락)',YEL],['uptransit','🟢 상승전이',GRN]];
  var rowsH='';
  for(var i=0;i<ROWS.length;i++){
    var q=b[ROWS[i][0]], fr=freq(q), pu=pctUp(q), av=avg(q);
    var nWarn=(q.n>0&&q.n<30)?'<span style="color:'+AMB+'">⚠</span>':'';
    rowsH+='<tr>'
      +'<td style="padding:4px 7px;font-weight:800;color:'+ROWS[i][2]+';font-size:10px">'+ROWS[i][1]+'</td>'
      +'<td style="padding:4px 7px;text-align:right;font-weight:700;color:'+T2+';font-size:10px">'+(fr!=null?fr.toFixed(1)+'%':'–')+'</td>'
      +'<td style="padding:4px 7px;text-align:right;color:'+T3+';font-size:9px">'+q.n+nWarn+'</td>'
      +'<td style="padding:4px 7px;text-align:right;font-weight:800;color:'+(pu==null?T3:(pu>=50?GRN:RED))+';font-size:10.5px">'+(pu!=null?pu.toFixed(0)+'%':'–')+'</td>'
      +'<td style="padding:4px 7px;text-align:right;font-weight:700;color:'+(av==null?T3:(av>=0?GRN:RED))+';font-size:9.5px">'+(av!=null?((av>=0?'+':'')+av.toFixed(1)+'%'):'–')+'</td>'
      +'</tr>';
  }
  // 판정
  var trFreq=freq(b.transit), trUp=pctUp(b.transit), beUp=pctUp(b.bear), trAv=avg(b.transit), beAv=avg(b.bear);
  var verdict='';
  if(trFreq!=null && trUp!=null && beUp!=null && b.transit.n>=20 && b.bear.n>=20){
    var freqOk=trFreq>=10, d=trUp-beUp;
    var f1='① 빈도 <b>'+trFreq.toFixed(1)+'%</b> — '+(freqOk?'<span style="color:'+GRN+'">실질 구간(≥10%)</span>':'<span style="color:'+T3+'">희소(&lt;10%)</span>');
    var f2='② 위험도 — 전이형 상승 <b>'+trUp.toFixed(0)+'%</b> vs 역배 <b>'+beUp.toFixed(0)+'%</b> ('+(d>=0?'+':'')+d.toFixed(0)+'p) · 평균 '+(trAv!=null?(trAv>=0?'+':'')+trAv.toFixed(1)+'%':'–')+' vs '+(beAv!=null?(beAv>=0?'+':'')+beAv.toFixed(1)+'%':'–');
    var concl;
    if(freqOk && d<=0) concl='<span style="color:'+RED+'">▶ 전이형 = 실질 하락 위험 구간(역배 이상). <b>S886 transit 발굴 대상</b> + ③재료변별(deadcat 불켜짐) 필요</span>';
    else if(freqOk && d<=5) concl='<span style="color:'+AMB+'">▶ 전이형 ≈ 역배 수준 위험. 발굴 후보 — ③재료변별로 진입가치 확인</span>';
    else if(!freqOk) concl='<span style="color:'+T3+'">▶ 전이형 희소 — 발굴 실익 낮음. 🟡 배너(주의 표시)로 종결</span>';
    else concl='<span style="color:'+GRN+'">▶ 전이형이 역배보다 안전(+'+d.toFixed(0)+'p) — 하락 아크 대상 아님. 배너로 충분</span>';
    verdict=f1+'<br>'+f2+'<br>'+concl;
  } else verdict='<span style="color:'+T3+'">표본 부족(전이형·역배 각 n≥20 필요) — 판단 보류'+(b.transit.n<20?' (전이형 n='+b.transit.n+')':'')+'</span>';
  var head='<div style="font-size:8.5px;color:'+T3+';line-height:1.5;margin-bottom:8px">🟡 <b>전이형 위험 측정</b> — 전 봉(발동 무관)을 장기배열 4버킷 분류. <b>전이형</b>=장기혼조(3선 미정렬)+단기비정배(게이트·레시피 범위 밖). ①빈도 ②상승률/평균수익 vs 역배(N10 후반평균). <b>전이형 ≤ 역배</b>=bear급 위험 확정→발굴 대상. ③재료변별(deadcat 불켜짐)은 봉별 f 필요→위험 확정 시 S886. off('+((res.offTotal||0))+'봉·웜업) 제외 · ⚠<b>in-sample</b>(0701)·n&lt;30 주의 · '+_esc(poolLbl||'')+' '+(res.stocksUsed||0)+'종목</div>';
  return head
    +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
    +'<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 7px">버킷</td><td style="padding:3px 7px;text-align:right">빈도</td><td style="padding:3px 7px;text-align:right">n</td><td style="padding:3px 7px;text-align:right">N10상승</td><td style="padding:3px 7px;text-align:right">평균</td></tr>'
    +rowsH+'</table>'
    +'<div style="font-size:9px;margin-top:6px;line-height:1.6">'+verdict+'</div>';
}

// ════════ [S886] 🔲 전이형 격자 분해 — S885 transitrisk가 전이형(장기mixed+단기약세)=역배급 위험(kr d=−1·coin d=0 확정·us d=+2 후보) 판정했으나, mixed는 반대 하위상태 2개(하락전이 60<120·120>200=고점붕괴/KCTC · 상승전이 60>120·120<200=바닥회복)의 평균이라 신호 희석 의심(사용자 발견). 장기배열을 인접비교(60vs120,120vs200)로 {정배·상승전이·하락전이·역배} 정밀분해 × 단기(정배/약세) → 하락전이가 진짜 위험셀인지·상승전이가 회복셀인지 가름. 미측정 블롭을 측정 셀로 축소 + 하락전이 확장 근거. baseRateScan(동일 N10) 재사용, mixed subtype는 prefix-sum SMA로 render서 계산(엔진 sma와 동일=마지막 N종가 평균·_scanStock 동일 봉인덱스). engine/signal 무변경·window-only·측정전용. ════════
async function _recipeTransitGridBracket(mk, sources, onProgress){
  if(!(window.SXCandleBT&&SXCandleBT.fetchRows600)) return { ok:false, reason:'캔들 fetch 미연결' };
  if(!(window.SXRecipeSignal&&SXRecipeSignal.baseRateScan)) return { ok:false, reason:'레시피 모듈 구버전(baseRateScan 없음) — 새로고침' };
  var list=[], seen={};
  for(var si=0;si<sources.length;si++){
    var source=sources[si], part=[];
    if(source==='watch'){ try{ part=(typeof _getWatchlist==='function'?(_getWatchlist(mk)||[]):[]).filter(function(x){return x&&x.code;}).map(function(x){return {code:x.code,name:x.name||x.code};}); }catch(_){ part=[]; } }
    else if(source==='mega'){ part=(typeof _DISCOVERY_POOL!=='undefined'?(_DISCOVERY_POOL[mk]||[]):[]).map(function(x){ return Array.isArray(x)?{code:x[0],name:x[1]}:{code:String(x),name:String(x)}; }); }
    else { try{ var p=(window.SXCandleBT&&SXCandleBT.getRepPool)?SXCandleBT.getRepPool(mk):[]; part=(p||[]).map(function(x){return {code:x[0],name:x[1]};}); }catch(_){ part=[]; } }
    for(var pi=0;pi<part.length;pi++){ var it=part[pi]; if(it&&it.code&&!seen[it.code]){ seen[it.code]=1; list.push(it); } }
  }
  if(!list.length) return { ok:false, reason:'측정 풀 비어있음' };
  var CAP=(sources.indexOf('mega')>=0)?220:40, use=list.slice(0,CAP);
  var _tgt=(typeof _btTargetBars==='function')?_btTargetBars(mk,'day'):600, _floor=Math.floor(_tgt*0.95);
  var MK=function(){ return { total:0, n:0, up:0, sret:0 }; };
  var cells={ bull:MK(), upT_st:MK(), upT_wk:MK(), dnT_st:MK(), dnT_wk:MK(), bear:MK(), mixEtc:MK() };
  var offTotal=0, stocksUsed=0;
  for(var i=0;i<use.length;i++){
    var s0=use[i];
    if(onProgress) onProgress(i+1, use.length, s0.name);
    await _trendBatchSleep(0);
    var rows=null; try{ rows=await SXCandleBT.fetchRows600(mk,'day',s0.code); }catch(e){}
    if(!Array.isArray(rows)||rows.length<_floor){ await _trendBatchSleep(6); continue; }
    var br=null; try{ br=await SXRecipeSignal.baseRateScan(s0.code, rows); }catch(e2){}
    if(!Array.isArray(br)||!br.length){ await _trendBatchSleep(6); continue; }
    var P=[0]; for(var pc=0;pc<rows.length;pc++){ var _c=(rows[pc]&&typeof rows[pc].close==='number')?rows[pc].close:0; P.push(P[P.length-1]+_c); }
    var smaAt=function(bi,p){ return (bi+1-p>=0)?((P[bi+1]-P[bi+1-p])/p):null; };
    var used=false;
    for(var bi2=0;bi2<br.length;bi2++){
      var r=br[bi2], key;
      if(r.lt==='bull') key='bull';
      else if(r.lt==='bear') key='bear';
      else if(r.lt==='mixed'){
        var m60=smaAt(r.bar,60), m120=smaAt(r.bar,120), m200=smaAt(r.bar,200);
        if(m60==null||m120==null||m200==null) key='mixEtc';
        else if(m60>m120 && m120<m200) key=r.stBull?'upT_st':'upT_wk';   // 상승전이=바닥회복
        else if(m60<m120 && m120>m200) key=r.stBull?'dnT_st':'dnT_wk';   // 하락전이=고점붕괴(KCTC)
        else key='mixEtc';                                               // 동률/엣지(희소)
      } else { offTotal++; continue; }                                   // off=웜업(장기MA 데이터부족)
      var q=cells[key]; q.total++;
      if(r.complete && r.ret!=null){ q.n++; if(r.up)q.up++; q.sret+=r.ret; }
      used=true;
    }
    if(used) stocksUsed++;
    await _trendBatchSleep(8);
  }
  if(stocksUsed<3) return { ok:false, reason:'유효 종목 3개 미만' };
  return { ok:true, cells:cells, offTotal:offTotal, stocksUsed:stocksUsed };
}
