function _maCrossFitRender(res, mk, poolLbl){
  var GRN='#16a34a', RED='#dc2626', AMB='#d97706', BLU='#2563eb', T2='var(--text2)', T3='var(--text3)';
  if(!res) return '';
  if(!res.ok) return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">🎚️ '+(res.reason||'측정 실패')+'</div>';
  var _esc=function(x){ return String(x==null?'':x).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); };
  var HZ=res.HZ, CX=res.CX;
  var upRate=function(cell){ return cell.n?cell.up/cell.n*100:null; };
  var disc=function(cr,h){ var u=upRate(CX[cr.id].up[h]), d=upRate(CX[cr.id].down[h]); return (u!=null&&d!=null)?(u-d):null; };
  var churn=function(cr){ return CX[cr.id].bars?CX[cr.id].churn/CX[cr.id].bars*1000:null; };
  var bestS=null, bestL=null;
  for(var i=0;i<res.crosses.length;i++){ var cr=res.crosses[i];
    if(cr.g==='S'){ var dv=disc(cr,10); if(dv!=null&&(bestS==null||dv>bestS.v)) bestS={id:cr.id,v:dv}; }
    else { var dv2=disc(cr,60); if(dv2!=null&&(bestL==null||dv2>bestL.v)) bestL={id:cr.id,v:dv2}; }
  }
  var cDisc=function(v){ return v==null?T3:(v>=10?GRN:(v>=5?AMB:(v<0?RED:T3))); };
  var mkRows=function(grp){
    var h='';
    for(var i=0;i<res.crosses.length;i++){ var cr=res.crosses[i]; if(cr.g!==grp) continue;
      var ch=churn(cr), best=(grp==='S'&&bestS&&bestS.id===cr.id)||(grp==='L'&&bestL&&bestL.id===cr.id);
      h+='<tr'+(best?' style="background:'+GRN+'12"':'')+'>'
        +'<td style="padding:4px 6px;font-weight:800;color:'+(best?GRN:T2)+';font-size:10px">'+cr.id+(cr.cur?'<span style="color:'+AMB+';font-size:8px"> ★</span>':'')+(best?' <span style="font-size:8px;color:'+GRN+'">◀최적</span>':'')+'</td>'
        +'<td style="padding:4px 6px;text-align:right;color:'+(ch==null?T3:(ch>=120?RED:(ch>=60?AMB:T2)))+';font-size:9.5px">'+(ch!=null?ch.toFixed(0):'–')+'</td>';
      for(var hi=0;hi<HZ.length;hi++){ var dv=disc(cr,HZ[hi]); var bold=((HZ[hi]===10&&grp==='S')||(HZ[hi]===60&&grp==='L'))?'800':'600';
        h+='<td style="padding:4px 6px;text-align:right;font-weight:'+bold+';color:'+cDisc(dv)+';font-size:10px">'+(dv!=null?((dv>=0?'+':'')+dv.toFixed(0)):'–')+'</td>'; }
      h+='</tr>';
    }
    return h;
  };
  var hdr='<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 6px">크로스</td><td style="padding:3px 6px;text-align:right">전환/1k</td>';
  for(var hj=0;hj<HZ.length;hj++){ hdr+='<td style="padding:3px 6px;text-align:right">N'+HZ[hj]+'변별</td>'; }
  hdr+='</tr>';
  var sec1='<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
    +hdr
    +'<tr><td colspan="'+(2+HZ.length)+'" style="padding:2px 6px;font-size:8px;font-weight:800;color:'+BLU+';background:'+BLU+'0d">단기 (강세/약세) — N10 변별 주목</td></tr>'
    +mkRows('S')
    +'<tr><td colspan="'+(2+HZ.length)+'" style="padding:2px 6px;font-size:8px;font-weight:800;color:'+RED+';background:'+RED+'0d">장기 (상승장/하락장) — N60 변별 주목</td></tr>'
    +mkRows('L')
    +'</table>';
  var CL=res.CL, tot=0; for(var kk in CL){ tot+=CL[kk][HZ[0]].n; }
  var clRow=function(key,lab,col){
    var st=CL[key], fr=tot?st[HZ[0]].n/tot*100:null;
    var seg='<td style="padding:4px 6px;font-weight:800;color:'+col+';font-size:9.5px">'+lab+'</td>'
      +'<td style="padding:4px 6px;text-align:right;color:'+T2+';font-size:9.5px">'+(fr!=null?fr.toFixed(0)+'%':'–')+'</td>';
    var hs=[10,60];
    for(var j=0;j<hs.length;j++){ var q=st[hs[j]], pu=q.n?q.up/q.n*100:null, av=q.n?q.ret/q.n*100:null;
      seg+='<td style="padding:4px 6px;text-align:right;font-weight:700;color:'+(pu==null?T3:(pu>=50?GRN:RED))+';font-size:10px">'+(pu!=null?pu.toFixed(0)+'%':'–')+'</td>'
        +'<td style="padding:4px 6px;text-align:right;color:'+(av==null?T3:(av>=0?GRN:RED))+';font-size:9px">'+(av!=null?((av>=0?'+':'')+av.toFixed(1)):'–')+'</td>'; }
    return '<tr>'+seg+'</tr>';
  };
  var sec2='<div style="font-size:9px;font-weight:800;color:'+T2+';margin:12px 0 4px">📐 단기클러스터(ma5·ma20) vs 장기클러스터(ma60·ma200) 위치</div>'
    +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
    +'<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 6px">위치</td><td style="padding:3px 6px;text-align:right">빈도</td><td style="padding:3px 6px;text-align:right">N10상승</td><td style="padding:3px 6px;text-align:right">N10평</td><td style="padding:3px 6px;text-align:right">N60상승</td><td style="padding:3px 6px;text-align:right">N60평</td></tr>'
    +clRow('above','🔼 단기 위',GRN)
    +clRow('mixed','▪️ 겹침',T3)
    +clRow('below','🔽 단기 아래',RED)
    +'</table>';
  var head='<div style="font-size:8.5px;color:'+T3+';line-height:1.5;margin-bottom:8px">🎚️ <b>MA 크로스 적합성</b> — 후보 크로스마다 <b>변별</b>(up상태 상승률 − down상태 상승률·%p·미래를 얼마나 가르나)과 <b>전환/1k봉</b>(낮을수록 regime 지속·휩쏘 적음). <b>단기(강세/약세)</b>=N10 변별↑ · <b>장기(상승장/하락장)</b>=N60 변별↑+전환↓이 적합. ★=현행 삼중선(5/20/60·60/120/200) 성분 · ◀최적=그룹 내 최고 · 발굴풀 전 봉 · ⚠<b>in-sample</b>(0701) · '+_esc(poolLbl||'')+' '+(res.stocksUsed||0)+'종목</div>';
  return head+sec1+sec2;
}

// ════════ [S888] 📊 시장평균 크로스 + 이격도 과열&침체 (번외2) — S887 macrossfit이 "단기 크로스=mean-reverting·MA크로스는 약한 변별자" 발견. 두 후속 렌즈: ①시장평균(등가중 수익지수=개별종목 노이즈 제거)에서 크로스 적합성 재측정 — 상승장/하락장을 시장 레벨서(사용자 원 질문 '시장평균'). ②이격도60(close/ma60×100) 5분위별 미래수익 — 과열=과매수→하락/침체=과매도→반등(mean-reversion)이 방향 변별자인지(사용자 지목 지표). rows서 prefix-sum SMA·날짜집계 지수로 전부 계산(engine/signal 무관)·window-only·🔬 미포함·측정전용. ════════
async function _dispRegimeBracket(mk, sources, onProgress){
  if(!(window.SXCandleBT&&SXCandleBT.fetchRows600)) return { ok:false, reason:'캔들 fetch 미연결' };
  var list=[], seen={};
  for(var si=0;si<sources.length;si++){
    var source=sources[si], part=[];
    if(source==='watch'){ try{ part=(typeof _getWatchlist==='function'?(_getWatchlist(mk)||[]):[]).filter(function(x){return x&&x.code;}).map(function(x){return {code:x.code,name:x.name||x.code};}); }catch(_){ part=[]; } }
    else if(source==='mega'){ part=(typeof _DISCOVERY_POOL!=='undefined'?(_DISCOVERY_POOL[mk]||[]):[]).map(function(x){ return Array.isArray(x)?{code:x[0],name:x[1]}:{code:String(x),name:String(x)}; }); }
    else { try{ var p=(window.SXCandleBT&&SXCandleBT.getRepPool)?SXCandleBT.getRepPool(mk):[]; part=(p||[]).map(function(x){return {code:x[0],name:x[1]};}); }catch(_){ part=[]; } }
    for(var pi=0;pi<part.length;pi++){ var it=part[pi]; if(it&&it.code&&!seen[it.code]){ seen[it.code]=1; list.push(it); } }
  }
  if(!list.length) return { ok:false, reason:'측정 풀 비어있음' };
  var CAP=(sources.indexOf('mega')>=0)?220:40, use=list.slice(0,CAP);
  var _tgt=(typeof _btTargetBars==='function')?_btTargetBars(mk,'day'):600, _floor=Math.floor(_tgt*0.95);
  var HZ=[10,20,60];
  var byDate={};   // 등가중 지수용: date -> {s:일수익합, c:종목수}
  var DR=[];       // 이격도 레코드: {d:close/ma60*100, r10,r20,r60}
  var stocksUsed=0;
  for(var i=0;i<use.length;i++){
    var s0=use[i];
    if(onProgress) onProgress(i+1, use.length, s0.name);
    await _trendBatchSleep(0);
    var rows=null; try{ rows=await SXCandleBT.fetchRows600(mk,'day',s0.code); }catch(e){}
    if(!Array.isArray(rows)||rows.length<_floor){ await _trendBatchSleep(6); continue; }
    for(var di=1;di<rows.length;di++){ var p0=(rows[di-1]&&typeof rows[di-1].close==='number')?rows[di-1].close:null, p1=(rows[di]&&typeof rows[di].close==='number')?rows[di].close:null; if(!(p0>0)||!(p1>0)) continue; var dt=rows[di].date; if(dt==null) continue; var bd=byDate[dt]||(byDate[dt]={s:0,c:0}); bd.s+=(p1/p0-1); bd.c++; }
    var P=[0]; for(var pc=0;pc<rows.length;pc++){ var _c=(rows[pc]&&typeof rows[pc].close==='number')?rows[pc].close:0; P.push(P[P.length-1]+_c); }
    var smaAt=function(bi,p){ return (bi+1-p>=0)?((P[bi+1]-P[bi+1-p])/p):null; };
    for(var bi=60;bi<rows.length;bi++){
      var cl=(rows[bi]&&typeof rows[bi].close==='number')?rows[bi].close:null, m60=smaAt(bi,60);
      if(!(cl>0)||m60==null||!(m60>0)) continue;
      var rec={d:cl/m60*100}, any=false;
      for(var hz=0;hz<HZ.length;hz++){ var b2=bi+HZ[hz]; var c2=(b2<rows.length&&rows[b2]&&typeof rows[b2].close==='number')?rows[b2].close:null; var vv=(c2>0)?(c2/cl-1):null; rec['r'+HZ[hz]]=vv; if(vv!=null)any=true; }
      if(any) DR.push(rec);
    }
    stocksUsed++;
    await _trendBatchSleep(9);
  }
  if(stocksUsed<3) return { ok:false, reason:'유효 종목 3개 미만' };
  // 등가중 수익지수
  var dates=Object.keys(byDate).sort(), idx=[], v=100;
  for(var dk=0;dk<dates.length;dk++){ var bb=byDate[dates[dk]]; if(bb.c>0) v=v*(1+bb.s/bb.c); idx.push(v); }
  var ICR=[{id:'5×20',f:5,s:20},{id:'20×60',f:20,s:60},{id:'60×200',f:60,s:200},{id:'120×200',f:120,s:200}];
  var IP=[0]; for(var ii=0;ii<idx.length;ii++){ IP.push(IP[IP.length-1]+idx[ii]); }
  var isma=function(bi,p){ return (bi+1-p>=0)?((IP[bi+1]-IP[bi+1-p])/p):null; };
  var idxCX={};
  for(var ci=0;ci<ICR.length;ci++){ var cr=ICR[ci];
    var stt={up:{},down:{}}; for(var h1=0;h1<HZ.length;h1++){ stt.up[HZ[h1]]={n:0,up:0,ret:0}; stt.down[HZ[h1]]={n:0,up:0,ret:0}; }
    var uN=0,dN=0;
    for(var bx=200;bx<idx.length;bx++){ var vf=isma(bx,cr.f), vs=isma(bx,cr.s); if(vf==null||vs==null) continue; var st=(vf>vs)?'up':'down'; if(st==='up')uN++; else dN++;
      for(var h2=0;h2<HZ.length;h2++){ var b2=bx+HZ[h2]; if(b2>=idx.length) continue; var fr=idx[b2]/idx[bx]-1; var a=stt[st][HZ[h2]]; a.n++; if(fr>0)a.up++; a.ret+=fr; } }
    idxCX[cr.id]={st:stt, upFrac:(uN+dN)?uN/(uN+dN)*100:null};
  }
  // 이격도60 5분위
  var disp=null;
  if(DR.length>=100){
    var ds=DR.map(function(x){return x.d;}).sort(function(a,b){return a-b;});
    var qq=function(p){ var k=Math.floor(p*ds.length); if(k>=ds.length)k=ds.length-1; return ds[k]; };
    var cut=[qq(0.2),qq(0.4),qq(0.6),qq(0.8)];
    disp=[]; for(var qi=0;qi<5;qi++){ var o={lo:null,hi:null}; for(var h3=0;h3<HZ.length;h3++){ o[HZ[h3]]={n:0,up:0,ret:0}; } disp.push(o); }
    for(var ri=0;ri<DR.length;ri++){ var rc=DR[ri], bkt=(rc.d<cut[0])?0:((rc.d<cut[1])?1:((rc.d<cut[2])?2:((rc.d<cut[3])?3:4))); var ab=disp[bkt];
      if(ab.lo==null||rc.d<ab.lo)ab.lo=rc.d; if(ab.hi==null||rc.d>ab.hi)ab.hi=rc.d;
      for(var h4=0;h4<HZ.length;h4++){ var w=rc['r'+HZ[h4]]; if(w!=null){ var aq=ab[HZ[h4]]; aq.n++; if(w>0)aq.up++; aq.ret+=w; } }
    }
  }
  return { ok:true, idxCX:idxCX, disp:disp, HZ:HZ, idxLen:idx.length, nDisp:DR.length, stocksUsed:stocksUsed };
}
async function _dispRegimeRun(){
  var el=document.getElementById('dispRegimeResult'); if(!el) return;
  var mk=(typeof currentMarket!=='undefined')?currentMarket:'kr';
  el.style.display='block';
  var _prog=function(lbl,i,t,n){ el.innerHTML='<div style="padding:10px;font-size:11px;color:var(--text2)">📊 '+lbl+' 스캔 '+i+'/'+t+' · '+(n||'')+'</div>'; };
  var res, poolLbl;
  if(window.SXCandleBT&&SXCandleBT.snapMode&&SXCandleBT.snapMode()){
    if(SXCandleBT.snapHas&&!SXCandleBT.snapHas(mk)){
      el.innerHTML='<div style="padding:10px;font-size:11px;font-weight:800;color:#0e7490">📂 '+String(mk).toUpperCase()+' 스냅샷 자동 로드…</div>';
      var _sr=await _snapLoad(mk);
      if(!_sr.ok){ el.innerHTML='<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">📂 '+_sr.reason+'</div>'; return; }
      if(typeof _snapBadge==='function') _snapBadge();
    }
    _prog('발굴풀',0,0,'시작');
    try{ res=await _dispRegimeBracket(mk,['mega'],function(i,t,n){_prog('발굴풀',i,t,n);}); }catch(eM){ res={ok:false,reason:String(eM&&eM.message||eM)}; }
    poolLbl='발굴풀(스냅샷)';
  } else {
    _prog('대표+관심',0,0,'시작');
    try{ res=await _dispRegimeBracket(mk,['rep','watch'],function(i,t,n){_prog('대표+관심',i,t,n);}); }catch(e){ res={ok:false,reason:String(e&&e.message||e)}; }
    poolLbl='대표+관심 합산';
  }
  _sxMeasStash('dispregime_'+mk, { poolLbl:poolLbl, res:res });   // [S888]
  el.innerHTML=_dispRegimeRender(res, mk, poolLbl);
}
function _dispRegimeRender(res, mk, poolLbl){
  var GRN='#16a34a', RED='#dc2626', AMB='#d97706', BLU='#2563eb', T2='var(--text2)', T3='var(--text3)';
  if(!res) return '';
  if(!res.ok) return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px;font-size:10.5px;color:#dc2626">📊 '+(res.reason||'측정 실패')+'</div>';
  var _esc=function(x){ return String(x==null?'':x).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); };
  var HZ=res.HZ;
  var ur=function(c){ return c.n?c.up/c.n*100:null; };
  var disc=function(st,h){ var u=ur(st.up[h]), d=ur(st.down[h]); return (u!=null&&d!=null)?(u-d):null; };
  var cD=function(v){ return v==null?T3:(v>=8?GRN:(v>=4?AMB:(v<0?RED:T3))); };
  // 섹션1: 시장평균 지수 크로스
  var ICR=['5×20','20×60','60×200','120×200'], s1='';
  for(var i=0;i<ICR.length;i++){ var o=res.idxCX[ICR[i]]; if(!o){ continue; }
    s1+='<tr><td style="padding:4px 6px;font-weight:800;color:'+T2+';font-size:10px">'+ICR[i]+'</td>'
      +'<td style="padding:4px 6px;text-align:right;color:'+T3+';font-size:9px">'+(o.upFrac!=null?o.upFrac.toFixed(0)+'%':'–')+'</td>';
    for(var h=0;h<HZ.length;h++){ var dv=disc(o.st,HZ[h]); s1+='<td style="padding:4px 6px;text-align:right;font-weight:700;color:'+cD(dv)+';font-size:10px">'+(dv!=null?((dv>=0?'+':'')+dv.toFixed(0)):'–')+'</td>'; }
    s1+='</tr>';
  }
  var sec1='<div style="font-size:9px;font-weight:800;color:'+T2+';margin:2px 0 4px">① 시장평균(등가중 수익지수) 크로스 <span style="font-weight:500;color:'+T3+';font-size:8px">· 지수 '+res.idxLen+'봉·개별노이즈 제거</span></div>'
    +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
    +'<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 6px">크로스</td><td style="padding:3px 6px;text-align:right">up빈도</td>'
    +HZ.map(function(h){return '<td style="padding:3px 6px;text-align:right">N'+h+'변별</td>';}).join('')+'</tr>'+s1+'</table>';
  // 섹션2: 이격도 5분위
  var sec2='';
  if(res.disp){
    var LB=[['최저(침체)',BLU],['저','#0891b2'],['중',T2],['고',AMB],['최고(과열)',RED]];
    var s2='';
    for(var qi=0;qi<5;qi++){ var q=res.disp[qi];
      var rng=(q.lo!=null&&q.hi!=null)?(q.lo.toFixed(0)+'~'+q.hi.toFixed(0)):'–';
      s2+='<tr><td style="padding:4px 6px;font-weight:800;color:'+LB[qi][1]+';font-size:9.5px">'+LB[qi][0]+'</td>'
        +'<td style="padding:4px 6px;text-align:right;color:'+T3+';font-size:8.5px">'+rng+'</td>';
      var hs=[10,60];
      for(var j=0;j<hs.length;j++){ var c=q[hs[j]], pu=c.n?c.up/c.n*100:null, av=c.n?c.ret/c.n*100:null;
        s2+='<td style="padding:4px 6px;text-align:right;font-weight:700;color:'+(pu==null?T3:(pu>=50?GRN:RED))+';font-size:10px">'+(pu!=null?pu.toFixed(0)+'%':'–')+'</td>'
          +'<td style="padding:4px 6px;text-align:right;color:'+(av==null?T3:(av>=0?GRN:RED))+';font-size:9px">'+(av!=null?((av>=0?'+':'')+av.toFixed(1)):'–')+'</td>'; }
      s2+='</tr>';
    }
    // 변별(최저−최고)
    var lo=res.disp[0], hi=res.disp[4];
    var d10=(lo[10].n&&hi[10].n)?(lo[10].up/lo[10].n*100 - hi[10].up/hi[10].n*100):null;
    var d60=(lo[60].n&&hi[60].n)?(lo[60].up/lo[60].n*100 - hi[60].up/hi[60].n*100):null;
    var vd;
    if(d10!=null&&d60!=null){
      var mr=(d10>=8||d60>=8);
      vd='변별(침체−과열): N10 <b>'+(d10>=0?'+':'')+d10.toFixed(0)+'p</b> · N60 <b>'+(d60>=0?'+':'')+d60.toFixed(0)+'p</b> — '
        +(mr?'<span style="color:'+GRN+'">mean-reversion 변별자 유효(침체=반등·과열=하락)</span>':((d10<=-8||d60<=-8)?'<span style="color:'+AMB+'">momentum(침체=계속하락·과열=계속상승)</span>':'<span style="color:'+T3+'">약함 — 이격도도 뚜렷한 변별자 아님</span>'));
    } else vd='<span style="color:'+T3+'">표본 부족</span>';
    sec2='<div style="font-size:9px;font-weight:800;color:'+T2+';margin:12px 0 4px">② 이격도60 과열&침체 <span style="font-weight:500;color:'+T3+';font-size:8px">· close/ma60×100 · 5분위 · n='+res.nDisp+'</span></div>'
      +'<table style="width:100%;border-collapse:collapse;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden">'
      +'<tr style="font-size:8px;color:'+T3+'"><td style="padding:3px 6px">분위</td><td style="padding:3px 6px;text-align:right">이격도</td><td style="padding:3px 6px;text-align:right">N10상승</td><td style="padding:3px 6px;text-align:right">N10평</td><td style="padding:3px 6px;text-align:right">N60상승</td><td style="padding:3px 6px;text-align:right">N60평</td></tr>'
      +s2+'</table>'
      +'<div style="font-size:9px;margin-top:5px;line-height:1.55">'+vd+'</div>';
  }
  var head='<div style="font-size:8.5px;color:'+T3+';line-height:1.5;margin-bottom:8px">📊 <b>시장평균 크로스 + 이격도</b> — ① 등가중 수익지수(개별종목 노이즈 제거)로 크로스 변별 재측정(상승장/하락장을 시장 레벨). 단일 지수라 표본 작음(±노이즈 주의). ② 이격도60(close/ma60×100) 5분위별 미래수익 — 침체(저)=반등·과열(고)=하락이면 mean-reversion 변별자. ⚠<b>in-sample</b>(0701) · '+_esc(poolLbl||'')+' '+(res.stocksUsed||0)+'종목</div>';
  return head+sec1+sec2;
}

