      items.sort(function(a,b){ var ea=(a.rec.retLens!=null?a.rec.retLens:-9)*(kind==='real'?1:-1), eb=(b.rec.retLens!=null?b.rec.retLens:-9)*(kind==='real'?1:-1); return eb-ea; });
