    _vis.forEach(it=>{ const _pp = _SXB_PARAM.has(it.k) || it.k.indexOf('이평선')===0;
      det += _sxbCircle(it.v, it.k, false, !!it.neutral, it.d, !!it.inverse, !!it.byValue, it.signal, _pp); });
