  const gap = (nl.need != null && nl.obs != null)
    ? `\n실측 ${nl.obs}%p인데, ${_MEAS_NULL_TH}%가 되려면 ${nl.need}%p가 필요했습니다(약 ${(nl.need / Math.abs(nl.obs)).toFixed(1)}배).`
    : '';
