    var SL=(_SV1272&&_SV1272.axisShort)||{bull:'강세',bear:'약세',mixed:'중립'}, LL=(_SV1272&&_SV1272.axisLong)||{bull:'상승세',bear:'하락세',mixed:'혼조세'};
